import React,{useEffect,useRef,useState} from 'react';
import {createRoot} from 'react-dom/client';
import {createClient} from '@supabase/supabase-js';
import './styles.css';
import logo from './assets/elo-logo.png';
import mark from './assets/elo-mark.png';
import grupoSystemLogo from './assets/grupo-system-logo.png';

const SUPABASE_URL=import.meta.env.VITE_SUPABASE_URL;
const SUPABASE_ANON_KEY=import.meta.env.VITE_SUPABASE_ANON_KEY;
const supabase=(SUPABASE_URL&&SUPABASE_ANON_KEY)?createClient(SUPABASE_URL,SUPABASE_ANON_KEY):null;
const nav=[['dashboard','Painel Executivo','⌂'],['demandas','Demandas','✓'],['solicitacoes','Solicitações','↗'],['ideias','Ideias','✦'],['projetos','Projetos','▣'],['arquivos','Arquivos','▤'],['destaques','Destaques','★'],['agenda','Agenda','◷'],['reunioes','Reuniões','◉'],['indicadores','Indicadores','▥'],['relatorios','Relatórios','▧']];
const data={demandas:[['Atualizar procedimento de atendimento','Alta','Mayara','Hoje','Em andamento'],['Relatório mensal de indicadores','Média','Rafael','30/09','Em análise'],['Treinamento da equipe','Média','Yasmin','03/10','Pendente'],['Melhoria do roteiro de atendimento','Baixa','Henrique','07/10','Em andamento']],solicitacoes:[['Verificar computador da recepção','Larissa','TI','Hoje','Em andamento'],['Troca de lâmpada da sala 2','Rafael','Manutenção','30/09','Pendente'],['Solicitar material de escritório','Yasmin','Administrativo','01/10','Em andamento'],['Acesso ao sistema de relatórios','Mayara','TI','02/10','Concluída']],ideias:[['Criar novo processo para reduzir tempo de espera','Henrique','Em análise','Alto'],['Implantar feedback digital do cliente','Mayara','Aprovada','Alto'],['Automatizar lembretes de reuniões','Rafael','Em desenvolvimento','Médio'],['Criar material de treinamento em vídeo','Yasmin','Em análise','Alto']],projetos:[['Novo processo de atendimento','Henrique','30/09','Em andamento'],['Implantação do sistema de relatórios','Rafael','15/10','Em andamento'],['Campanha interna de endomarketing','Mayara','25/10','Planejamento'],['Treinamento da equipe','Yasmin','05/11','Em andamento']]};
function Icon({children}){return <span className="icon">{children}</span>}
function Login({onLogin}){
 const [email,setEmail]=useState('');
 const [password,setPassword]=useState('');
 const [loading,setLoading]=useState(false);
 const [error,setError]=useState('');
 const [notice,setNotice]=useState('');
 const [mode,setMode]=useState('login');
 const submit=async e=>{
   e.preventDefault();setError('');setNotice('');
   if(!supabase){setError('Configure VITE_SUPABASE_URL e VITE_SUPABASE_ANON_KEY antes de usar o login.');return}
   setLoading(true);
   const {data,error}=await supabase.auth.signInWithPassword({email,password});
   setLoading(false);
   if(error){setError('E-mail ou senha inválidos.');return}
   const {data:profile,error:profileError}=await supabase.from('profiles').select('status').eq('id',data.user.id).single();
   if(profileError||!profile||profile.status!=='ativo'){await supabase.auth.signOut();setError('Seu acesso não está ativo. Procure o administrador do ELO.');return}
   onLogin(data.session)
 };
 const sendReset=async e=>{
   e.preventDefault();setError('');setNotice('');
   if(!supabase){setError('O serviço de autenticação não está configurado.');return}
   if(!email.trim()){setError('Informe o e-mail cadastrado para receber o link de recuperação.');return}
   setLoading(true);
   const redirectTo=`${window.location.origin}/?reset-password=1`;
   const {error}=await supabase.auth.resetPasswordForEmail(email.trim(),{redirectTo});
   setLoading(false);
   if(error){setError('Não foi possível enviar o e-mail de recuperação. Verifique a configuração de URLs no Supabase e tente novamente.');return}
   setNotice('Se esse e-mail estiver cadastrado, você receberá um link para redefinir sua senha. Verifique também a caixa de spam.');
 };
 return <div className="loginPage"><div className="loginGlow"></div><div className="loginCard"><img src={logo} className="loginLogo"/><div className="loginBrand">ELO</div><p className="loginTag">GESTÃO • ORGANIZAÇÃO • RESULTADOS</p><div className="loginIntro"><h1>{mode==='login'?'Acesso privado':'Recuperar senha'}</h1><p>{mode==='login'?'Entre com as credenciais fornecidas pelo administrador.':'Informe o e-mail vinculado à sua conta ELO para receber o link de recuperação.'}</p></div>{mode==='login'?<form onSubmit={submit}><label>E-mail<input type="email" value={email} onChange={e=>setEmail(e.target.value)} required autoComplete="username" placeholder="seu@email.com"/></label><label>Senha<input type="password" value={password} onChange={e=>setPassword(e.target.value)} required autoComplete="current-password" placeholder="••••••••"/></label>{error&&<div className="errorBox">{error}</div>}<button className="primary loginButton" disabled={loading}>{loading?'Entrando…':'Entrar no ELO'}</button><button type="button" className="textLink" onClick={()=>{setMode('recovery');setError('');setNotice('')}}>Esqueceu sua senha?</button></form>:<form onSubmit={sendReset}><label>E-mail cadastrado<input type="email" value={email} onChange={e=>setEmail(e.target.value)} required autoComplete="email" placeholder="seu@email.com"/></label>{error&&<div className="errorBox">{error}</div>}{notice&&<div className="notice">{notice}</div>}<button className="primary loginButton" disabled={loading}>{loading?'Enviando…':'Enviar link de recuperação'}</button><button type="button" className="textLink" onClick={()=>{setMode('login');setError('');setNotice('')}}>Voltar para o login</button></form>}<p className="loginFooter">Acesso restrito a usuários autorizados.</p></div></div>}
function ResetPassword({onBack,hasSession}){
 const [password,setPassword]=useState('');
 const [confirm,setConfirm]=useState('');
 const [loading,setLoading]=useState(false);
 const [error,setError]=useState('');
 const [success,setSuccess]=useState(false);
 const save=async e=>{
   e.preventDefault();setError('');
   if(password.length<8){setError('A nova senha deve ter pelo menos 8 caracteres.');return}
   if(password!==confirm){setError('As senhas não correspondem.');return}
   if(!supabase){setError('O serviço de autenticação não está configurado.');return}
   setLoading(true);
   const {error}=await supabase.auth.updateUser({password});
   setLoading(false);
   if(error){setError('Não foi possível alterar a senha. O link pode ter expirado; solicite um novo link de recuperação.');return}
   setSuccess(true);
   await supabase.auth.signOut();
   window.history.replaceState({},document.title,window.location.pathname);
 };
 return <div className="loginPage"><div className="loginGlow"></div><div className="loginCard"><img src={logo} className="loginLogo"/><div className="loginBrand">ELO</div><p className="loginTag">GESTÃO • ORGANIZAÇÃO • RESULTADOS</p><div className="loginIntro"><h1>Nova senha</h1><p>Crie uma nova senha para recuperar o acesso à sua conta.</p></div>{!hasSession?<><div className="errorBox">Este link de recuperação é inválido ou expirou. Solicite um novo link na tela de login.</div><button className="primary loginButton" onClick={onBack}>Voltar para o login</button></>:success?<><div className="notice">Senha alterada com sucesso. Você já pode entrar no ELO com a nova senha.</div><button className="primary loginButton" onClick={onBack}>Voltar para o login</button></>:<form onSubmit={save}><label>Nova senha<input type="password" value={password} onChange={e=>setPassword(e.target.value)} required minLength={8} autoComplete="new-password" placeholder="Mínimo de 8 caracteres"/></label><label>Confirmar nova senha<input type="password" value={confirm} onChange={e=>setConfirm(e.target.value)} required minLength={8} autoComplete="new-password" placeholder="Digite a senha novamente"/></label>{error&&<div className="errorBox">{error}</div>}<button className="primary loginButton" disabled={loading}>{loading?'Salvando…':'Salvar nova senha'}</button><button type="button" className="textLink" onClick={onBack}>Voltar para o login</button></form>}<p className="loginFooter">Acesso restrito a usuários autorizados.</p></div></div>}
function App({session,profile}){const [page,setPage]=useState('dashboard');const [menu,setMenu]=useState(false);const [light,setLight]=useState(false);const [showUsers,setShowUsers]=useState(false);const [newRequestSignal,setNewRequestSignal]=useState(0);const title=nav.find(n=>n[0]===page)?.[1]||'Dashboard';const email=session?.user?.email||'Usuário';const displayName=profile?.full_name||email;const initials=(displayName[0]||'N').toUpperCase();
 const logout=async()=>{if(supabase)await supabase.auth.signOut()};
 return <div className={light?'app light':'app'}><header className="topbar"><button className="menuBtn" onClick={()=>setMenu(true)} aria-label="Abrir menu"><span></span><span></span><span></span></button><div className="brand"><img src={mark}/><div><strong>ELO</strong><small>GESTÃO • ORGANIZAÇÃO • RESULTADOS</small></div></div><div className="topActions"><button className="ghost" onClick={()=>setLight(!light)}>{light?'☾':'☼'}</button><button className="bell">♧<i></i></button><div className="user"><div className="avatar">{initials}</div><div><b>{displayName}</b><small>{profile?.role||'Usuário autorizado'}</small></div></div></div></header><main className="main"><div className="heading"><div><p className="eyebrow">VISÃO GERAL</p><h1>{title}</h1><p className="muted">Acompanhe pessoas, ideias, demandas e resultados em um só lugar.</p></div>{page==='solicitacoes'&&<button className="primary headingAction" onClick={()=>setNewRequestSignal(v=>v+1)}>＋ Nova solicitação</button>}</div>{page==='dashboard'&&<Dashboard currentUser={profile}/>}{page==='demandas'&&<DemandasManager currentUser={profile}/>} {page==='solicitacoes'&&<SolicitacoesManager currentUser={profile} openSignal={newRequestSignal}/>} {['ideias','projetos','arquivos','agenda','reunioes'].includes(page)&&<OperationalRecordsManager page={page} currentUser={profile}/>} {page==='indicadores'&&<IndicadoresManager currentUser={profile}/>} {page==='destaques'&&<DestaquesManager currentUser={profile}/>} {page==='relatorios'&&<RelatoriosManager currentUser={profile}/>} {showUsers&&<UserManager onClose={()=>setShowUsers(false)}/>}</main>{menu&&<><div className="overlay" onClick={()=>setMenu(false)}></div><aside className="drawer"><div className="drawerHead"><div className="brand"><img src={mark}/><div><strong>ELO</strong><small>GESTÃO • ORGANIZAÇÃO • RESULTADOS</small></div></div><button onClick={()=>setMenu(false)}>×</button></div><nav>{nav.map(([id,label,ic])=><button key={id} className={page===id?'active':''} onClick={()=>{setPage(id);setMenu(false)}}><Icon>{ic}</Icon>{label}</button>)}</nav><div className="drawerBottom"><button onClick={()=>{setShowUsers(true);setMenu(false)}}><Icon>♙</Icon> Usuários</button><button><Icon>⚙</Icon> Configurações</button><button onClick={logout}><Icon>↪</Icon> Sair</button><div className="profile"><div className="avatar">{initials}</div><div><b>{displayName}</b><small>{profile?.role||'Conta autenticada'}</small></div></div></div></aside></>}</div>}
function Dashboard({currentUser}){
 const role=String(currentUser?.role||'').toLowerCase();
 const [view,setView]=useState(['supervisor','supervisora'].includes(role)?'supervisao':'diretoria');
 const [refresh,setRefresh]=useState(0);
 const [stats,setStats]=useState({demandas:null,solicitacoes:null,projetos:null,ideias:null,registros:null,metas:null,qualidade:null});
 const [statuses,setStatuses]=useState({demandas:null,solicitacoes:null,projetos:null,ideias:null});
 const [overdue,setOverdue]=useState(null);
 const [rel,setRel]=useState({obsMes:null,relMes:null,demAbertas:null,semDemanda:null});
 const [loading,setLoading]=useState(true);const [warnings,setWarnings]=useState([]);const [lastUpdated,setLastUpdated]=useState(null);
 const fmt=v=>v===null||v===undefined?'—':Number(v).toLocaleString('pt-BR',{maximumFractionDigits:0});
 const statusLabels={nova:'Novas',em_analise:'Em análise',em_andamento:'Em andamento',aguardando:'Aguardando',concluida:'Concluídas',cancelada:'Canceladas',aprovada:'Aprovadas',recusada:'Recusadas',demanda_gerada:'Demanda gerada',planejamento:'Planejamento',pausado:'Pausados',concluido:'Concluídos',cancelado:'Cancelados',implementada:'Implementadas',em_desenvolvimento:'Em desenvolvimento'};
 useEffect(()=>{let active=true;(async()=>{
   setLoading(true);const warn=[];const next={demandas:null,solicitacoes:null,projetos:null,ideias:null,registros:null,metas:null,qualidade:null};const statusNext={demandas:null,solicitacoes:null,projetos:null,ideias:null};let overdueCount=null;
   if(!supabase){if(active){setStats(next);setStatuses(statusNext);setWarnings(['Supabase não configurado']);setLoading(false)}return}
   const count=async(table,key,query)=>{let q=supabase.from(table).select('id',{count:'exact',head:true});if(query)q=query(q);const {count:total,error}=await q;if(error){warn.push(`${key}: fonte indisponível`);return null}return total??0};
   const statusesFor=async(table,key,values)=>{const items=[];for(const value of values){let q=supabase.from(table).select('id',{count:'exact',head:true}).eq('status',value);const {count:total,error}=await q;if(error){return null}if((total??0)>0)items.push({key:value,label:statusLabels[value]||value.replaceAll('_',' '),count:total})}return items};
   const [d,s,p,i,r,m,q]=await Promise.all([
    count('demandas','Demandas'),count('solicitacoes','Solicitações'),count('projetos','Projetos'),count('ideias','Ideias'),count('indicadores_registros','Central de Dados'),count('indicadores_metas','Metas'),count('destaque_avaliacoes','Avaliações de qualidade',q=>q.not('quality_avg_100','is',null))
   ]);
   Object.assign(next,{demandas:d,solicitacoes:s,projetos:p,ideias:i,registros:r,metas:m,qualidade:q});
   const [ds,ss,ps,is]=await Promise.all([
    statusesFor('demandas','Demandas',['nova','em_analise','em_andamento','aguardando','concluida','cancelada']),
    statusesFor('solicitacoes','Solicitações',['nova','em_analise','aprovada','recusada','demanda_gerada']),
    statusesFor('projetos','Projetos',['planejamento','em_andamento','pausado','concluido','cancelado']),
    statusesFor('ideias','Ideias',['nova','em_analise','aprovada','em_desenvolvimento','implementada','recusada'])
   ]);
   statusNext.demandas=ds;statusNext.solicitacoes=ss;statusNext.projetos=ps;statusNext.ideias=is;
   const today=new Date();const todayKey=`${today.getFullYear()}-${String(today.getMonth()+1).padStart(2,'0')}-${String(today.getDate()).padStart(2,'0')}`;
   const {count:late,error:lateError}=await supabase.from('demandas').select('id',{count:'exact',head:true}).lt('due_date',todayKey).not('status','in','("concluida","cancelada")');
   if(lateError){warn.push('Prazos de demandas: fonte indisponível')}else overdueCount=late??0;
   if(active){setStats(next);setStatuses(statusNext);setOverdue(overdueCount);setWarnings([...new Set(warn)]);setLastUpdated(new Date());setLoading(false)}
  })();return()=>{active=false}},[refresh]);
 useEffect(()=>{let active=true;(async()=>{if(!supabase)return;const now=new Date();const pd=n=>String(n).padStart(2,'0');const first=`${now.getFullYear()}-${pd(now.getMonth()+1)}-01`;const next={obsMes:null,relMes:null,demAbertas:null,semDemanda:null};
   const c1=await supabase.from('relatorio_observacoes').select('id',{count:'exact',head:true}).gte('obs_date',first);if(!c1.error)next.obsMes=c1.count??0;
   const c2=await supabase.from('relatorios').select('id',{count:'exact',head:true}).gte('created_at',`${first}T00:00:00`);if(!c2.error)next.relMes=c2.count??0;
   const lk=await supabase.from('relatorio_solucao_demandas').select('report_id,problema,solucao,demanda_id,demandas(status)').limit(2000);
   if(!lk.error){const rows=lk.data||[];next.demAbertas=rows.filter(l=>l.demanda_id&&l.demandas&&!['concluida','cancelada'].includes(l.demandas.status)).length;
    const since=new Date(Date.now()-90*86400000).toISOString();const rp=await supabase.from('relatorios').select('id,solucoes:content->solucoes').gte('created_at',since).limit(300);
    if(!rp.error){const done=new Set(rows.filter(l=>l.demanda_id).map(l=>`${l.report_id}\u0001${l.problema}\u0001${l.solucao}`));let n=0;(rp.data||[]).forEach(r=>(Array.isArray(r.solucoes)?r.solucoes:[]).forEach(x=>(x.solucoes||[]).forEach(y=>{if(!done.has(`${r.id}\u0001${x.problema}\u0001${y}`))n++})));next.semDemanda=n}}
   if(active)setRel(next)})();return()=>{active=false}},[refresh]);
 const cards=view==='supervisao'?
  [{n:stats.demandas,t:'Demandas registradas',s:'Total de registros acessíveis',icon:'✓'},{n:overdue,t:'Demandas vencidas',s:'Prazo anterior a hoje, não concluídas',icon:'!'},{n:stats.solicitacoes,t:'Solicitações',s:'Total de registros acessíveis',icon:'↗'},{n:stats.qualidade,t:'Avaliações com nota',s:'Registros com pontuação de qualidade',icon:'★'}]:
  [{n:stats.demandas,t:'Demandas',s:'Volume registrado na operação',icon:'✓'},{n:stats.solicitacoes,t:'Solicitações',s:'Volume registrado no sistema',icon:'↗'},{n:stats.projetos,t:'Projetos',s:'Iniciativas cadastradas',icon:'▣'},{n:stats.registros,t:'Registros de indicadores',s:'Central de Dados: manual/CSV/integrações',icon:'▥'}];
 const total=(items)=>items?.reduce((sum,x)=>sum+x.count,0)||0;
 const StatusPanel=({title,subtitle,items})=><div className="execStatusPanel"><div className="panelTitle"><div><h3>{title}</h3><span>{subtitle}</span></div></div>{items===null?<div className="execEmpty">Fonte indisponível ou sem permissão de leitura.</div>:items.length===0?<div className="execEmpty">Nenhum registro com os status conhecidos foi encontrado.</div>:<div className="execStatusList">{items.map(item=><div className="execStatusRow" key={item.key}><span>{item.label}</span><div className="execTrack"><i style={{width:`${Math.max(3,total(items)?item.count/total(items)*100:0)}%`}}/></div><b>{fmt(item.count)}</b></div>)}</div>}</div>;
 return <section className="executiveDashboard">
  <div className="execToolbar"><div><span className="execEyebrow">ELO • GESTÃO POR DADOS</span><h2>{view==='supervisao'?'Controle operacional':'Visão estratégica'}</h2><p>{view==='supervisao'?'Acompanhe pendências e o estado atual da operação.':'Acompanhe volumes registrados e a disponibilidade das fontes.'}</p></div><div className="execActions"><div className="execSwitch" role="group" aria-label="Visão do painel"><button className={view==='supervisao'?'active':''} onClick={()=>setView('supervisao')}>Supervisão</button><button className={view==='diretoria'?'active':''} onClick={()=>setView('diretoria')}>Diretoria</button></div><button className="secondary execRefresh" onClick={()=>setRefresh(v=>v+1)} disabled={loading}>{loading?'Atualizando…':'↻ Atualizar'}</button></div></div>
  <div className="execCards">{cards.map((c,idx)=><div className="execCard" key={c.t}><div className="execCardTop"><span className="execCardIcon">{c.icon}</span><span className="execCardIndex">0{idx+1}</span></div><strong>{loading?'…':fmt(c.n)}</strong><b>{c.t}</b><small>{c.s}</small></div>)}</div>
  {view==='supervisao'?<div className="execStatusGrid"><StatusPanel title="Demandas por status" subtitle="Distribuição dos registros acessíveis" items={statuses.demandas}/><StatusPanel title="Solicitações por status" subtitle="Distribuição dos registros acessíveis" items={statuses.solicitacoes}/></div>:<div className="execStatusGrid"><StatusPanel title="Projetos por status" subtitle="Distribuição dos registros acessíveis" items={statuses.projetos}/><StatusPanel title="Ideias por status" subtitle="Distribuição dos registros acessíveis" items={statuses.ideias}/></div>}
  <div className="panel execReportPanel"><div className="panelTitle"><div><h3>Relatórios e problemas em aberto</h3><span>Observações do mês, relatórios gerados e acompanhamento das soluções sugeridas</span></div></div><div className="execMiniGrid">{[{n:rel.obsMes,t:'Observações no mês',s:'Registradas no módulo Relatórios'},{n:rel.relMes,t:'Relatórios gerados no mês',s:'Semanais, mensais e personalizados'},{n:rel.demAbertas,t:'Problemas em acompanhamento',s:'Demandas de relatórios ainda abertas'},{n:rel.semDemanda,t:'Soluções sem demanda',s:'Sugeridas nos últimos 90 dias'}].map(x=><div className="execMini" key={x.t}><strong>{loading?'…':fmt(x.n)}</strong><b>{x.t}</b><small>{x.s}</small></div>)}</div></div>
  <div className="execBottomGrid"><div className="panel execSourcePanel"><div className="panelTitle"><div><h3>{view==='supervisao'?'Atenção operacional':'Base para decisões estratégicas'}</h3><span>Somente informações confirmadas pelas fontes conectadas</span></div></div>{view==='supervisao'?<><div className="execInsight"><span className="execInsightIcon">!</span><div><b>{loading?'Verificando prazos…':overdue===null?'Prazos indisponíveis':`${fmt(overdue)} demanda(s) vencida(s)`}</b><small>Contagem por prazo desejado anterior à data atual e status diferente de concluída/cancelada.</small></div></div><div className="execInsight"><span className="execInsightIcon">★</span><div><b>{loading?'…':stats.qualidade===null?'Avaliações indisponíveis':`${fmt(stats.qualidade)} avaliação(ões) com pontuação`}</b><small>Para consultar as notas e o histórico, abra o módulo Destaques.</small></div></div></>:<><div className="execInsight"><span className="execInsightIcon">▥</span><div><b>{loading?'…':stats.registros===null?'Central de Dados indisponível':`${fmt(stats.registros)} registro(s) de indicadores`}</b><small>Registros manuais ou importados. O total não representa produtividade por si só.</small></div></div><div className="execInsight"><span className="execInsightIcon">◎</span><div><b>{loading?'…':stats.metas===null?'Metas indisponíveis':`${fmt(stats.metas)} meta(s) cadastrada(s)`}</b><small>Realizado versus meta só será calculado após validar indicador, período, unidade e setor.</small></div></div></>}</div><div className="panel execSourcePanel"><div className="panelTitle"><div><h3>Fontes e confiabilidade</h3><span>Estado das consultas realizadas</span></div></div><div className="execSourceRow"><span className={stats.demandas===null?'sourceUnknown':'sourceOk'}></span><div><b>Supabase / módulos operacionais</b><small>{stats.demandas===null||stats.solicitacoes===null?'Uma ou mais fontes indisponíveis':'Consultas de contagem e status disponíveis'}</small></div></div><div className="execSourceRow"><span className={stats.registros===null||stats.metas===null?'sourceUnknown':'sourceOk'}></span><div><b>Central de Indicadores</b><small>{stats.registros===null||stats.metas===null?'Fonte indisponível ou sem permissão':'Registros e metas consultados no banco'}</small></div></div><div className="execSourceRow"><span className="sourceNeutral"></span><div><b>CSV e integrações futuras</b><small>Importações existentes entram na Central de Dados; novas integrações ainda não estão configuradas neste painel.</small></div></div></div></div>
  {warnings.length>0&&<div className="notice warn execWarning"><b>Verifique as fontes:</b> {warnings.join(' • ')}. A indisponibilidade não é interpretada como zero.</div>}
  <div className="execFooter"><span>{lastUpdated?`Última atualização: ${lastUpdated.toLocaleTimeString('pt-BR',{hour:'2-digit',minute:'2-digit',second:'2-digit'})}`:'Aguardando primeira consulta'}</span><span>Valores consultados no Supabase; nenhum dado demonstrativo.</span></div>
 </section>
}
function Stat({n,t,s}){return <div className="stat"><div className="statIcon">◈</div><div><strong>{n}</strong><b>{t}</b><small>{s}</small></div></div>}


function DestaquesManager({currentUser}){
 const [tab,setTab]=useState('visao');
 const monthKey=new Date().toISOString().slice(0,7); const monthLabel=new Date().toLocaleDateString('pt-BR',{month:'long',year:'numeric'});
 const [criteria,setCriteria]=useState([]); const [members,setMembers]=useState([]); const [references,setReferences]=useState([]); const [criterionRefs,setCriterionRefs]=useState([]); const [cycle,setCycle]=useState(null); const [cycles,setCycles]=useState([]); const [selectedPeriodKey,setSelectedPeriodKey]=useState(monthKey); const [loading,setLoading]=useState(true);
 const [modal,setModal]=useState(null); const [msg,setMsg]=useState(''); const [busy,setBusy]=useState(false);
 const [form,setForm]=useState({name:'',description:'',weight:10,source:'ia',min_score:0,required:true,active:true});
 const [teamForm,setTeamForm]=useState({id:'',full_name:'',sector:'Atendimento',status:'ativo'});
 const [pdf,setPdf]=useState(null); const [selectedEmployee,setSelectedEmployee]=useState(''); const [attendances,setAttendances]=useState([]); const [selectedAttendance,setSelectedAttendance]=useState(null);
 const [monthlyEmployee,setMonthlyEmployee]=useState(''); const [monthlyItems,setMonthlyItems]=useState([]); const [monthlyEvaluation,setMonthlyEvaluation]=useState(null); const [monthlyLoading,setMonthlyLoading]=useState(false); const [monthlySaving,setMonthlySaving]=useState(false);
 const [manualDraft,setManualDraft]=useState({}); const [ranking,setRanking]=useState([]); const [rankingLoading,setRankingLoading]=useState(false);
 const selectedPeriodCycle=cycles.find(x=>x.period_key===selectedPeriodKey)||cycle;
 const currentPeriodLabel=cycle?new Date(`${cycle.period_start}T00:00:00`).toLocaleDateString('pt-BR',{month:'long',year:'numeric'}):monthLabel;
 const activeAiCriteria=criteria.filter(c=>c.active&&c.source==='ia');
 const manualCriteria=criteria.filter(c=>c.active&&c.source!=='ia');
 const load=async()=>{setLoading(true);setMsg('');
   const [{data:c},{data:m},{data:refs},{data:links},{data:cy,error},{data:allCycles},{data:a}]=await Promise.all([
     supabase.from('destaque_criterios').select('*').order('created_at',{ascending:true}),
     supabase.from('destaque_colaboradores').select('*').order('full_name',{ascending:true}),
     supabase.from('destaque_referencias_ia').select('*').order('created_at',{ascending:true}),
     supabase.from('destaque_criterio_referencias').select('*').order('priority',{ascending:true}),
     supabase.from('destaque_ciclos').select('*').eq('period_key',monthKey).limit(1).maybeSingle(),
     supabase.from('destaque_ciclos').select('*').order('period_key',{ascending:false}),
     supabase.from('destaque_atendimentos').select('*, employee:employee_id(id,full_name,sector)').is('evaluation_deleted_at',null).order('created_at',{ascending:false}).limit(200)
   ]);
   if(error)setMsg(error.message); setCriteria(c||[]);setMembers(m||[]);setReferences(refs||[]);setCriterionRefs(links||[]);setCycle(cy||null);setCycles(allCycles||[]);setAttendances(a||[]);if(cy&&!selectedPeriodKey)setSelectedPeriodKey(cy.period_key);setLoading(false);
 };
 useEffect(()=>{load()},[]);
 useEffect(()=>{if(!monthlyEmployee&&members.find(m=>m.status==='ativo'))setMonthlyEmployee(members.find(m=>m.status==='ativo').id)},[members,monthlyEmployee]);
 const openTeamMember=(m=null)=>{setTeamForm(m?{id:m.id,full_name:m.full_name||'',sector:m.sector||'Atendimento',status:m.status||'ativo'}:{id:'',full_name:'',sector:'Atendimento',status:'ativo'});setModal(m?'team-edit':'team');setMsg('')};
 const saveTeamMember=async e=>{e.preventDefault();setBusy(true);setMsg('');const payload={full_name:teamForm.full_name.trim(),sector:teamForm.sector.trim()||'Atendimento',status:teamForm.status};const r=teamForm.id?await supabase.from('destaque_colaboradores').update(payload).eq('id',teamForm.id):await supabase.from('destaque_colaboradores').insert({...payload,created_by:(await supabase.auth.getUser()).data.user.id});if(r.error)setMsg(r.error.message);else{await load();setModal(null)}setBusy(false)};
 const removeTeamMember=async id=>{if(!confirm('Desativar este colaborador da equipe de avaliação?'))return;const {error}=await supabase.from('destaque_colaboradores').update({status:'inativo'}).eq('id',id);if(error)setMsg(error.message);else{if(selectedEmployee===id)setSelectedEmployee('');load()}};
 const openCriterion=(c=null)=>{setForm(c?{id:c.id,name:c.name,description:c.description||'',weight:c.weight,source:c.source,min_score:c.min_score,required:c.required,active:c.active}:{name:'',description:'',weight:10,source:'ia',min_score:0,required:true,active:true});setModal(c?'criterion-edit':'criterion');setMsg('')};
 const saveCriterion=async e=>{e.preventDefault();setBusy(true);setMsg('');const payload={name:form.name,description:form.description||null,weight:Number(form.weight),source:form.source,min_score:Number(form.min_score||0),required:!!form.required,active:!!form.active};let r=form.id?await supabase.from('destaque_criterios').update(payload).eq('id',form.id):await supabase.from('destaque_criterios').insert({...payload,created_by:(await supabase.auth.getUser()).data.user.id});if(r.error)setMsg(r.error.message);else{await load();setModal(null)}setBusy(false)};
 const removeCriterion=async id=>{if(!confirm('Excluir este critério?'))return;const {error}=await supabase.from('destaque_criterios').delete().eq('id',id);if(error)setMsg(error.message);else load()};
 const createCycle=async()=>{setBusy(true);const {data,error}=await supabase.from('destaque_ciclos').insert({period_key:monthKey,period_start:`${monthKey}-01`,period_end:new Date(new Date(`${monthKey}-01T00:00:00`).getFullYear(),new Date(`${monthKey}-01T00:00:00`).getMonth()+1,0).toISOString().slice(0,10),team_name:'Equipe',status:'em_avaliacao',created_by:(await supabase.auth.getUser()).data.user.id}).select().single();if(error)setMsg(error.message);else setCycle(data);setBusy(false)};
 const readFnError=async(fn)=>{if(fn.data?.error)return fn.data.error;const ctx=fn.error?.context;if(ctx&&typeof ctx.clone==='function'){try{const b=await ctx.clone().json();if(b?.error)return b.error;if(b?.message)return b.message}catch{}try{const t=await ctx.clone().text();if(t)return t}catch{}}return fn.error?.message||'Erro desconhecido.'};
 const uploadAttendance=async()=>{
   if(!pdf||!selectedEmployee){setMsg('Selecione o colaborador e o arquivo (PDF ou TXT) antes de continuar.');return}
   const lowerName=pdf.name.toLowerCase(); const isPdf=lowerName.endsWith('.pdf')||pdf.type==='application/pdf'; const isTxt=lowerName.endsWith('.txt')||pdf.type==='text/plain';
   if(!isPdf&&!isTxt){setMsg('Formato não suportado. Envie um arquivo PDF ou TXT.');return}
   if(isPdf&&pdf.size>14*1024*1024){setMsg('PDF muito grande. Envie um arquivo de até 14 MB.');return}
   if(isTxt&&pdf.size>2*1024*1024){setMsg('TXT muito grande. Envie um arquivo de até 2 MB.');return}
   setBusy(true);setMsg('');
   try{
     const {data:userData,error:userError}=await supabase.auth.getUser(); if(userError||!userData?.user)throw new Error('Sessão do usuário não encontrada. Faça login novamente.'); const uid=userData.user.id;
     let activeCycle=cycle;
     if(!activeCycle){
       const start=new Date(`${monthKey}-01T00:00:00`);
       const end=new Date(start.getFullYear(),start.getMonth()+1,0);
       const created=await supabase.from('destaque_ciclos').upsert({period_key:monthKey,period_start:`${monthKey}-01`,period_end:end.toISOString().slice(0,10),team_name:'Equipe',status:'em_avaliacao',created_by:uid},{onConflict:'period_key'}).select().single();
       if(created.error||!created.data)throw new Error(`Não foi possível preparar o ciclo mensal: ${created.error?.message||'ciclo não retornado.'}`);
       activeCycle=created.data; setCycle(activeCycle);
     }
     const {data:employee,error:employeeError}=await supabase.from('destaque_colaboradores').select('id,full_name,status').eq('id',selectedEmployee).maybeSingle();
     if(employeeError)throw new Error(`Não foi possível validar o colaborador: ${employeeError.message}`); if(!employee)throw new Error('O colaborador selecionado não existe mais na equipe avaliada.'); if(employee.status!=='ativo')throw new Error('O colaborador selecionado está inativo.');
     const {data:cycleRow,error:cycleError}=await supabase.from('destaque_ciclos').select('id').eq('id',activeCycle.id).maybeSingle(); if(cycleError||!cycleRow)throw new Error('O ciclo de avaliação não foi encontrado. Atualize a página.');
     const safeName=pdf.name.replace(/[^a-zA-Z0-9._-]/g,'_'); const path=`${uid}/${activeCycle.id}/${crypto.randomUUID()}-${safeName}`;
     const up=await supabase.storage.from('destaque-atendimentos').upload(path,pdf,{contentType:isPdf?'application/pdf':'text/plain',upsert:false}); if(up.error)throw new Error(`Falha ao enviar o arquivo: ${up.error.message}`);
     const {data:attendance,error:insertError}=await supabase.from('destaque_atendimentos').insert({cycle_id:activeCycle.id,employee_id:employee.id,storage_path:path,file_name:pdf.name,status:'aguardando_analise',created_by:uid}).select().single();
     if(insertError){await supabase.storage.from('destaque-atendimentos').remove([path]);throw new Error(`Não foi possível registrar o atendimento: ${insertError.message}`)}
     const fn=await supabase.functions.invoke('analyze-attendance',{body:{attendance_id:attendance.id}});
     if(fn.error||fn.data?.success===false){const reason=await readFnError(fn);setMsg(`Arquivo enviado, mas a análise falhou: ${reason}`)} else if(fn.data?.monthly_warning)setMsg(`Análise individual salva no histórico, mas a consolidação mensal precisa de atenção: ${fn.data.monthly_warning}`); else setMsg('Atendimento analisado e salvo no histórico. As notas de qualidade e script foram registradas.');
     await load(); setPdf(null); setSelectedAttendance(null);
   }catch(error){setMsg(error instanceof Error?error.message:String(error))}finally{setBusy(false)}
 };
 const deleteAttendanceEvaluation=async(attendance)=>{
   if(!attendance?.id)return;
   if(!confirm(`Excluir a avaliação de \"${attendance.file_name}\"?\n\nO arquivo será preservado, mas a análise e a pontuação deste atendimento deixarão de compor o mês.`))return;
   setBusy(true);setMsg('');
   try{
     const fn=await supabase.functions.invoke('delete-attendance-evaluation',{body:{attendance_id:attendance.id}});
     if(fn.error||fn.data?.success===false)throw new Error(fn.data?.error||fn.error?.message||'Não foi possível excluir a avaliação.');
     if(selectedAttendance?.id===attendance.id)setSelectedAttendance(null);
     await load();
     await loadMonthly(monthlyEmployee);
     await loadRanking(selectedPeriodKey);
     setMsg('Avaliação excluída. O arquivo foi preservado e pode ser analisado novamente.');
   }catch(error){setMsg(error instanceof Error?error.message:String(error))}finally{setBusy(false)}
 };
 const loadMonthly=async(employeeId=monthlyEmployee)=>{
   if(!employeeId||!selectedPeriodCycle){setMonthlyItems([]);setMonthlyEvaluation(null);return}
   setMonthlyLoading(true);setMsg('');
   const {data:evaluation,error:eError}=await supabase.from('destaque_avaliacoes').select('*').eq('cycle_id',selectedPeriodCycle.id).eq('employee_id',employeeId).maybeSingle();
   if(eError){setMsg(eError.message);setMonthlyLoading(false);return}
   if(evaluation){
     const {data:items,error:iError}=await supabase.from('destaque_avaliacao_itens').select('*').eq('evaluation_id',evaluation.id).order('created_at',{ascending:true});
     if(iError)setMsg(iError.message); setMonthlyEvaluation(evaluation); setMonthlyItems(items||[]);
   }else{setMonthlyEvaluation(null);setMonthlyItems([])}
   setMonthlyLoading(false);
 };
 const loadRanking=async(periodKey=selectedPeriodKey)=>{
   if(!periodKey){setRanking([]);return}
   setRankingLoading(true);
   const {data,error}=await supabase.from('vw_destaque_ranking_mensal').select('*').eq('period_key',periodKey).order('final_score',{ascending:false,nullsLast:true}).order('full_name',{ascending:true});
   if(error)setMsg(`Não foi possível carregar o ranking: ${error.message}`); else setRanking(data||[]);
   setRankingLoading(false);
 };
 useEffect(()=>{if(tab==='mensal')loadMonthly()},[tab,monthlyEmployee,selectedPeriodCycle?.id]);
 useEffect(()=>{if(tab==='ranking')loadRanking(selectedPeriodKey)},[tab,selectedPeriodKey]);
 const ensureEvaluation=async()=>{
   if(!selectedPeriodCycle||!monthlyEmployee)throw new Error('Selecione o colaborador e tenha um ciclo mensal ativo.');
   if(monthlyEvaluation)return monthlyEvaluation;
   const {data,error}=await supabase.from('destaque_avaliacoes').insert({cycle_id:selectedPeriodCycle.id,employee_id:monthlyEmployee,status:'em_avaliacao',eligible:true}).select().single();
   if(error){if(error.code==='23505'){const {data:existing}=await supabase.from('destaque_avaliacoes').select('*').eq('cycle_id',selectedPeriodCycle.id).eq('employee_id',monthlyEmployee).single();if(existing){setMonthlyEvaluation(existing);return existing}}throw new Error(error.message)}
   setMonthlyEvaluation(data);return data;
 };
 const refreshMonthly=async()=>{setMsg('');if(monthlyEvaluation?.id){const {error}=await supabase.rpc('recalculate_destaque_evaluation',{p_evaluation_id:monthlyEvaluation.id});if(error)setMsg(`Não foi possível atualizar a consolidação: ${error.message}`)}await loadMonthly(monthlyEmployee);await loadRanking(selectedPeriodKey)};
 const saveManualScores=async()=>{
   setMonthlySaving(true);setMsg('');
   try{
     const evaluation=await ensureEvaluation(); const {data:userData}=await supabase.auth.getUser(); const rows=[];
     for(const criterion of manualCriteria){
       const raw=manualDraft[criterion.id];
       if(raw===undefined||raw==='')continue;
       const maxPoints=Number(criterion.weight||0); const score=Math.max(0,Math.min(maxPoints,Number(raw))); if(!Number.isFinite(score))continue;
       rows.push({evaluation_id:evaluation.id,criterion_id:criterion.id,criterion_name_snapshot:criterion.name,weight_snapshot:Number(criterion.weight||0),source_snapshot:criterion.source,score:null,manual_score:Math.round(score*10)/10,manual_justification:manualDraft[`${criterion.id}_justification`]||null,manual_by:userData?.user?.id||null,manual_at:new Date().toISOString()});
     }
     if(rows.length){const {error}=await supabase.from('destaque_avaliacao_itens').upsert(rows,{onConflict:'evaluation_id,criterion_id'});if(error)throw new Error(error.message)}
     const {error:recalcError}=await supabase.rpc('recalculate_destaque_evaluation',{p_evaluation_id:evaluation.id});
     if(recalcError)throw new Error(`Pontuações salvas, mas não foi possível recalcular a avaliação: ${recalcError.message}`);
     await loadMonthly(monthlyEmployee); setMsg('Pontuações do gestor salvas e avaliação mensal recalculada.');
     await loadRanking(selectedPeriodKey);
   }catch(error){setMsg(error instanceof Error?error.message:String(error))}finally{setMonthlySaving(false)}
 };
 const monthlyScoreMap=Object.fromEntries(monthlyItems.map(i=>[i.criterion_id,i]));
 const manualTotal=manualCriteria.filter(c=>monthlyScoreMap[c.id]?.manual_score!==null&&monthlyScoreMap[c.id]?.manual_score!==undefined).reduce((sum,c)=>sum+Number(monthlyScoreMap[c.id].manual_score),0);
 const aiTotal=activeAiCriteria.filter(c=>monthlyScoreMap[c.id]?.score!==null&&monthlyScoreMap[c.id]?.score!==undefined).reduce((sum,c)=>sum+Number(monthlyScoreMap[c.id].score),0);
 const weightedTotal=manualTotal+aiTotal; const scoredWeight=[...activeAiCriteria,...manualCriteria].filter(c=>monthlyScoreMap[c.id]&&(monthlyScoreMap[c.id].score!==null||monthlyScoreMap[c.id].manual_score!==null)).reduce((sum,c)=>sum+Number(c.weight||0),0);
 const totalWeight=criteria.filter(c=>c.active).reduce((a,c)=>a+Number(c.weight||0),0);
 return <section className="destaquesPage">
   <div className="destaqueHero"><div><p className="eyebrow">MOTOR DE AVALIAÇÃO</p><h2>Destaque do Mês</h2><p>Configure os critérios, analise atendimentos e consolide a avaliação mensal da equipe.</p></div><div className="cycleBox"><span>PERÍODO ATUAL</span><b>{currentPeriodLabel.charAt(0).toUpperCase()+currentPeriodLabel.slice(1)}</b><em>{cycle?'Em avaliação':'Não iniciado'}</em></div></div>
   <div className="destaqueTabs"><button className={tab==='visao'?'active':''} onClick={()=>setTab('visao')}>Visão geral</button><button className={tab==='equipe'?'active':''} onClick={()=>setTab('equipe')}>Equipe</button><button className={tab==='criterios'?'active':''} onClick={()=>setTab('criterios')}>Critérios</button><button className={tab==='mensal'?'active':''} onClick={()=>setTab('mensal')}>Pontuação mensal</button><button className={tab==='ranking'?'active':''} onClick={()=>setTab('ranking')}>Ranking do mês</button><button className={tab==='ia'?'active':''} onClick={()=>setTab('ia')}>Base da IA</button><button className={tab==='atendimentos'?'active':''} onClick={()=>setTab('atendimentos')}>Análise de atendimentos</button><button className={tab==='historico'?'active':''} onClick={()=>setTab('historico')}>Histórico</button></div>
   {msg&&<div className="notice">{msg}</div>}
   {loading?<div className="placeholder"><div className="bigIcon">…</div><h2>Carregando avaliação</h2></div>:<>
   {tab==='visao'&&<div className="destaqueGrid"><div className="panel destaqueMain"><div className="panelTitle"><div><h3>🏆 Consolidação do mês</h3><span>O resultado será calculado a partir dos critérios configurados.</span></div></div>{!cycle?<div className="startCycle"><div className="bigIcon">★</div><h3>Inicie o ciclo de avaliação</h3><p>O ciclo de {monthLabel} ainda não foi criado. Os critérios podem ser configurados antes de iniciar.</p><button className="primary" onClick={createCycle} disabled={busy}>＋ Iniciar avaliação de {monthLabel}</button></div>:<div className="cycleOverview"><div><strong>{criteria.filter(c=>c.active).length}</strong><span>Critérios ativos</span></div><div><strong>{totalWeight}%</strong><span>Peso configurado</span></div><div><strong>{members.filter(m=>m.status==='ativo').length}</strong><span>Colaboradores ativos</span></div><div><strong>{attendances.filter(a=>a.cycle_id===cycle.id&&a.status==='analisado').length}</strong><span>Atendimentos analisados</span></div></div>}</div><div className="panel"><div className="panelTitle"><div><h3>Como o ELO decide</h3><span>Fluxo do motor</span></div></div><div className="flow"><div>01 <b>Atendimentos</b><small>PDFs por colaborador e mês</small></div><div>02 <b>Notas</b><small>IA + gestor</small></div><div>03 <b>Elegibilidade</b><small>Requisitos mínimos</small></div><div>04 <b>Resultado</b><small>Pontuação ponderada</small></div></div></div></div>}
   {tab==='equipe'&&<div className="panel criterioPanel"><div className="panelTitle"><div><h3>Equipe avaliada</h3><span>Cadastre quem participa do Destaque do Mês. O cadastro é independente dos usuários de acesso.</span></div><button className="primary" onClick={()=>openTeamMember()}>＋ Novo colaborador</button></div><div className="criteriaMeta"><span>{members.filter(m=>m.status==='ativo').length} ativos</span><span>{members.length} cadastrados</span><small>Os registros históricos permanecem mesmo quando alguém é desativado.</small></div><div className="criteriaList">{members.length===0?<div className="emptyState"><div className="bigIcon">＋</div><b>Nenhum colaborador cadastrado</b><span>Adicione a equipe que será avaliada.</span></div>:members.map(m=><div className="criterionRow teamRow" key={m.id}><div className="criterionIcon">♙</div><div className="criterionInfo"><b>{m.full_name}</b><small>{m.sector||'Atendimento'}</small></div><span className="criterionSource">{m.status==='ativo'?'Ativo':'Inativo'}</span><span className="criterionWeight">{attendances.filter(a=>a.employee_id===m.id&&(!selectedPeriodKey||a.period_key===selectedPeriodKey)).length}</span><span className={m.status==='ativo'?'criterionActive':'criterionInactive'}>{m.status==='ativo'?'Avaliado':'Inativo'}</span><div className="criterionActions"><button onClick={()=>openTeamMember(m)}>Editar</button><button onClick={()=>removeTeamMember(m.id)} disabled={m.status==='inativo'}>{m.status==='ativo'?'Desativar':'Inativo'}</button></div></div>)}</div></div>}
   {tab==='criterios'&&<div className="panel criterioPanel"><div className="panelTitle"><div><h3>Critérios de avaliação</h3><span>Defina o que será avaliado e de onde vem cada nota.</span></div><button className="primary" onClick={()=>openCriterion()}>＋ Novo critério</button></div><div className="criteriaMeta"><span>{criteria.filter(c=>c.active).length} ativos</span><span>Peso total: <b>{totalWeight}%</b></span><small>Os campos usam a pontuação máxima oficial de cada critério; total máximo de 100 pontos.</small></div><div className="criteriaList">{criteria.length===0?<div className="emptyState"><div className="bigIcon">＋</div><b>Nenhum critério configurado</b><span>Cadastre os critérios que irão compor o Destaque do Mês.</span></div>:criteria.map(c=><div className="criterionRow" key={c.id}><div className="criterionIcon">{c.source==='ia'?'✦':c.source==='sistema'?'▥':'♙'}</div><div className="criterionInfo"><b>{c.name}</b><small>{c.description||'Sem descrição'}</small></div><span className="criterionSource">{c.source==='ia'?'IA':c.source==='sistema'?'Sistema':'Manual'}</span><span className="criterionWeight">{c.weight}%</span><span className={c.active?'criterionActive':'criterionInactive'}>{c.active?'Ativo':'Inativo'}</span><div className="criterionActions"><button onClick={()=>openCriterion(c)}>Editar</button><button onClick={()=>removeCriterion(c.id)}>Excluir</button></div></div>)}</div></div>}
   {tab==='mensal'&&<div className="monthlyArea"><div className="panel monthlyHeader"><div><p className="eyebrow">AVALIAÇÃO MENSAL</p><h3>Notas por colaborador</h3><span>Selecione uma pessoa para visualizar o mês atual. A IA preenche os critérios de atendimento e o gestor registra os demais.</span></div><div className="monthlySelector"><label>Período<select value={selectedPeriodKey} onChange={e=>setSelectedPeriodKey(e.target.value)}>{cycles.map(x=><option key={x.period_key} value={x.period_key}>{new Date(`${x.period_start}T00:00:00`).toLocaleDateString('pt-BR',{month:'long',year:'numeric'})}</option>)}{!cycles.length&&<option value={monthKey}>{monthLabel}</option>}</select></label><label>Colaborador<select value={monthlyEmployee} onChange={e=>setMonthlyEmployee(e.target.value)}><option value="">Selecione...</option>{members.map(m=><option key={m.id} value={m.id}>{m.full_name}{m.status==='inativo'?' — Inativo':''}</option>)}</select></label></div></div>{!selectedPeriodCycle?<div className="panel emptyState"><div className="bigIcon">★</div><b>Este período ainda não possui ciclo de avaliação.</b><span>Inicie o ciclo do mês em Visão geral para registrar a pontuação.</span></div>:!monthlyEmployee?<div className="panel emptyState"><div className="bigIcon">♙</div><b>Selecione um colaborador.</b></div>:monthlyLoading?<div className="panel emptyState">Carregando pontuação…</div>:<><div className="monthlySummary"><div><span>Colaborador</span><strong>{members.find(m=>m.id===monthlyEmployee)?.full_name||'—'}</strong></div><div><span>Qualidade do Atendimento</span><strong>{monthlyEvaluation?.quality_avg_100!=null?`${Number(monthlyEvaluation.quality_avg_100).toFixed(1)} / 100`:'—'}</strong><small>{(()=>{const qc=criteria.find(c=>c.active&&/qualidade do atendimento/i.test(c.name));const qi=qc?monthlyScoreMap[qc.id]:null;const qs=qi?(qi.reviewed_score??qi.manual_score??qi.score):null;return qs!=null?`${Number(qs).toFixed(1)} / ${Number(qc.weight||0)} pontos`:(monthlyEvaluation?.quality_points_15!=null?`${monthlyEvaluation.quality_points_15} / 15 pontos`:'Aguardando atendimentos analisados')})()}</small></div><div><span>Script e Processos</span><strong>{monthlyEvaluation?.script_avg_10!=null?`${Number(monthlyEvaluation.script_avg_10).toFixed(1)} / 10`:'—'}</strong><small>{monthlyEvaluation?.ai_attendance_count||0} atendimento(s) consolidados</small></div><div><span>Peso avaliado</span><strong>{scoredWeight.toFixed(0)}%</strong></div><div><span>Pontuação final</span><strong>{weightedTotal.toFixed(2)} / {totalWeight.toFixed(0)}</strong></div><div><span>Status</span><strong>{scoredWeight>=totalWeight?'Completa':'Em andamento'}</strong></div></div><div className="panel monthlyPanel"><div className="panelTitle"><div><h3>Composição da pontuação</h3><span>Os critérios de IA são consolidados automaticamente a partir dos atendimentos analisados deste mês.</span></div><button className="secondary" onClick={refreshMonthly}>↻ Atualizar</button></div><div className="monthlyCriteria">{criteria.filter(c=>c.active).map(c=>{const item=monthlyScoreMap[c.id];const isAi=c.source==='ia';const score=item?(item.reviewed_score??item.manual_score??item.score):null;const samples=isAi?Number(item?.ai_samples||0):null;return <div className="monthlyCriterion" key={c.id}><div className="monthlyCriterionIcon">{isAi?'✦':'♙'}</div><div className="monthlyCriterionInfo"><b>{c.name}</b><small>{isAi?'IA • '+samples+' atendimento(s) consolidados':'Gestor • preenchimento manual'} • peso {c.weight}%</small>{item?.manual_justification&&<p>{item.manual_justification}</p>}</div><div className="monthlyScoreBox">{score!==null&&score!==undefined?<strong>{Number(score).toFixed(1)}</strong>:<span>—</span>}<small>{isAi?'IA':'Manual'} • / {Number(c.weight||0)} pts</small></div></div>})}</div></div>{manualCriteria.length>0&&<div className="panel manualPanel"><div className="panelTitle"><div><p className="eyebrow">PREENCHIMENTO DO GESTOR</p><h3>Adicionar pontuação dos demais critérios</h3><span>As notas abaixo ficam salvas somente para o colaborador e o período selecionados.</span></div><button className="primary" onClick={saveManualScores} disabled={monthlySaving}>{monthlySaving?'Salvando…':'Salvar pontuações'}</button></div><div className="manualGrid">{manualCriteria.map(c=>{const existing=monthlyScoreMap[c.id];const value=manualDraft[c.id]!==undefined?manualDraft[c.id]:(existing?.manual_score??'');return <div className="manualCriterion" key={c.id}><div><b>{c.name}</b><small>{c.source==='sistema'?'Sistema / gestor':'Manual'} • máximo {c.weight} pontos{c.required?' • obrigatório':''}</small></div><div className="manualInputRow"><input type="number" min="0" max={Number(c.weight||0)} step="0.1" value={value} onChange={e=>setManualDraft({...manualDraft,[c.id]:e.target.value})} placeholder={`0 a ${Number(c.weight||0)}`}/><span>/ {Number(c.weight||0)} pts</span></div><textarea value={manualDraft[`${c.id}_justification`]!==undefined?manualDraft[`${c.id}_justification`]:(existing?.manual_justification||'')} onChange={e=>setManualDraft({...manualDraft,[`${c.id}_justification`]:e.target.value})} placeholder="Observação do gestor (opcional)" rows="2"/></div>})}</div></div>}</>}</div>}
   {tab==='ranking'&&<div className="rankingArea"><div className="panel rankingHeader"><div><p className="eyebrow">CONSOLIDAÇÃO MENSAL</p><h3>Ranking de pontuação</h3><span>A posição é calculada automaticamente somando todas as pontuações de cada colaborador: as da IA e as lançadas pelo gestor.</span></div><div className="monthlySelector rankingSelector"><label>Competência<select value={selectedPeriodKey} onChange={e=>setSelectedPeriodKey(e.target.value)}>{cycles.map(x=><option key={x.period_key} value={x.period_key}>{new Date(`${x.period_start}T00:00:00`).toLocaleDateString('pt-BR',{month:'long',year:'numeric'})}</option>)}{!cycles.length&&<option value={monthKey}>{monthLabel}</option>}</select></label></div></div>{rankingLoading?<div className="panel emptyState">Carregando ranking…</div>:ranking.length===0?<div className="panel emptyState"><div className="bigIcon">★</div><b>Nenhuma avaliação mensal disponível.</b><span>As avaliações aparecem aqui quando houver pontuação consolidada para o período.</span></div>:<><div className="rankingSummary"><div><span>Colaboradores avaliados</span><strong>{ranking.length}</strong></div><div><span>Atendimentos analisados</span><strong>{ranking.reduce((sum,r)=>sum+Number(r.atendimentos_analisados||0),0)}</strong></div><div><span>Média dos pontuados</span><strong>{(()=>{const a=ranking.filter(r=>r.final_score!==null);return a.length?(a.reduce((s,r)=>s+Number(r.final_score),0)/a.length).toFixed(2):'—'})()}</strong></div><div><span>Avaliações completas</span><strong>{ranking.filter(r=>r.complete??(r.final_score!==null&&r.eligible)).length}</strong></div></div><div className="panel rankingPanel"><div className="rankingList">{ranking.map((r,index)=>{const hasScore=r.final_score!==null&&r.final_score!==undefined;const full=r.complete??hasScore;const maxPts=Number(r.max_points||100);const f1=v=>Number(v||0).toFixed(1).replace(/\.0$/,'');return <div className={'rankingRow '+(!hasScore?'rankingIncomplete':'')} key={r.evaluation_id}><div className="rankingPosition">{hasScore?(r.position??index+1):'—'}</div><div className="rankingAvatar">{(r.full_name||'?').slice(0,1).toUpperCase()}</div><div className="rankingPerson"><b>{r.full_name}</b><small>{r.sector||'Atendimento'} • {Number(r.atendimentos_analisados||0)} atendimento(s) analisado(s)</small>{hasScore&&r.ai_points!==undefined&&<small>IA {f1(r.ai_points)} pts • Gestor {f1(r.manual_points)} pts</small>}{!hasScore&&<em>Nenhuma pontuação lançada ainda</em>}{hasScore&&!full&&<em>Parcial: {r.scored_criteria} de {r.total_criteria} critérios pontuados</em>}</div><div className="rankingScore">{hasScore?<strong>{Number(r.final_score).toFixed(2)}<small> / {maxPts}</small></strong>:<strong>—</strong>}<small>{hasScore?(full?'Pontuação final':'Pontuação parcial'):'Sem pontuação'}</small></div></div>})}</div></div></>}</div>}
   {tab==='ia'&&<div className="destaqueGrid"><div className="panel criterioPanel"><div className="panelTitle"><div><p className="eyebrow">BASE DE CONHECIMENTO</p><h3>Referências utilizadas pela IA</h3><span>A IA recebe a referência vinculada ao critério e usa esse material como padrão.</span></div></div>{references.length===0?<div className="emptyState"><div className="bigIcon">✦</div><b>Nenhuma referência cadastrada</b><span>Execute o SQL de referências para cadastrar o roteiro oficial.</span></div>:<div className="criteriaList">{references.map(r=>{const links=criterionRefs.filter(x=>x.reference_id===r.id);const linkedNames=links.map(x=>criteria.find(c=>c.id===x.criterion_id)?.name).filter(Boolean);return <div className="criterionRow" key={r.id}><div className="criterionIcon">✦</div><div className="criterionInfo"><b>{r.name}</b><small>{r.reference_type} • versão {r.version}</small><small>{linkedNames.length?`Vinculada a: ${linkedNames.join(', ')}`:'Ainda não vinculada a nenhum critério'}</small></div><span className={r.active?'criterionActive':'criterionInactive'}>{r.active?'Ativa':'Inativa'}</span></div>})}</div>}</div><div className="panel"><div className="panelTitle"><div><h3>Roteiro oficial</h3><span>Base atual da avaliação de Qualidade do Atendimento.</span></div></div>{references.filter(r=>r.slug==='system-saude-roteiro-atendimento').map(r=><div className="analysisSummary" key={r.id}><b>{r.name}</b><br/><small>Versão {r.version}</small><pre style={{whiteSpace:'pre-wrap',fontFamily:'inherit',marginTop:'14px',lineHeight:'1.55'}}>{r.content}</pre></div>)}</div></div>}
   {tab==='atendimentos'&&<div className="attendanceArea"><div className="destaqueGrid"><div className="panel uploadPanel"><div className="panelTitle"><div><h3>Analisar atendimento</h3><span>Envie o PDF ou TXT do atendimento. A competência será identificada pela data do atendimento no documento.</span></div></div><label className="fieldLabel">Colaborador<select value={selectedEmployee} onChange={e=>{setSelectedEmployee(e.target.value);setSelectedAttendance(null)}}><option value="">Selecione...</option>{members.filter(m=>m.status==='ativo').map(m=><option key={m.id} value={m.id}>{m.full_name}</option>)}</select></label><label className="dropzone"><input type="file" accept=".pdf,.txt,application/pdf,text/plain" onChange={e=>setPdf(e.target.files?.[0]||null)}/><span>＋</span><b>{pdf?pdf.name:'Selecionar PDF ou TXT do atendimento'}</b><small>PDF ou TXT • análise protegida no servidor</small></label><button className="primary full" disabled={busy||!pdf||!selectedEmployee} onClick={uploadAttendance}>{busy?'Enviando / analisando…':'Analisar atendimento com IA'}</button>{msg&&<div className="hint resultMsg">{msg}</div>}</div><div className="panel"><div className="panelTitle"><div><h3>Especialista de atendimento</h3><span>Qualidade: 0–100 convertida para 15 pontos • Script e processos: 0–10 pontos por atendimento</span></div></div><div className="aiCriterion"><span>✦</span><div><b>Qualidade do Atendimento</b><small>Nota de 0 a 100 por atendimento; média mensal convertida para até 15 pontos.</small></div></div><div className="aiCriterion"><span>✓</span><div><b>Utilização do Script e Processos</b><small>Nota independente de 0 a 10 por atendimento, baseada nos sete critérios oficiais.</small></div></div></div></div><div className="panel attendanceHistory"><div className="panelTitle"><div><p className="eyebrow">PERÍODO</p><h3>Atendimentos de {members.find(m=>m.id===selectedEmployee)?.full_name||'colaborador'}</h3><span>Somente as avaliações deste colaborador aparecem no período selecionado.</span></div><div className="periodMiniSelect"><select value={selectedPeriodKey} onChange={e=>setSelectedPeriodKey(e.target.value)}>{cycles.map(x=><option key={x.period_key} value={x.period_key}>{new Date(`${x.period_start}T00:00:00`).toLocaleDateString('pt-BR',{month:'short',year:'numeric'})}</option>)}{!cycles.length&&<option value={monthKey}>{monthLabel}</option>}</select></div><span className="attendanceCount">{selectedEmployee?attendances.filter(a=>a.employee_id===selectedEmployee&&(!selectedPeriodKey||a.period_key===selectedPeriodKey)).length:0}</span></div>{!selectedEmployee?<div className="emptyMini">Selecione um colaborador para visualizar os atendimentos.</div>:(()=>{const list=attendances.filter(a=>a.employee_id===selectedEmployee&&(!selectedPeriodKey||a.period_key===selectedPeriodKey));return list.length===0?<div className="emptyMini">Nenhuma avaliação registrada para este colaborador neste período.</div>:<div className="attendanceList">{list.map(a=>{const total=a.analysis?.quality_score_100??a.analysis?.nota_total??null;return <div className={'attendanceItem '+(selectedAttendance?.id===a.id?'selected':'')} key={a.id} onClick={()=>setSelectedAttendance(a)} role="button" tabIndex={0} onKeyDown={e=>{if(e.key==='Enter'||e.key===' ')setSelectedAttendance(a)}}><div className="attendanceFile"><span>{/\.txt$/i.test(a.file_name||'')?'TXT':'PDF'}</span><div><b>{a.file_name}</b><small>{a.attendance_date?new Date(`${a.attendance_date}T00:00:00`).toLocaleDateString('pt-BR'):new Date(a.created_at).toLocaleString('pt-BR')} • {a.period_key||'período não identificado'}</small></div></div><div className="attendanceStatus"><strong>{a.status==='analisado'&&total!==null?total.toFixed(1):'—'}</strong><small>{a.status==='analisado'?'Qualidade / 100':a.status==='analisando'?'Analisando…':a.status==='erro'?'Erro':'Aguardando'}</small></div><button type="button" className="attendanceDelete" title="Excluir avaliação" disabled={busy} onClick={e=>{e.stopPropagation();deleteAttendanceEvaluation(a)}}>×</button></div>})}</div>})()}</div>{selectedAttendance&&selectedAttendance.employee_id===selectedEmployee&&<div className="panel analysisResult"><div className="panelTitle"><div><p className="eyebrow">AVALIAÇÃO ESPECIALISTA</p><h3>{selectedAttendance.employee?.full_name||'Atendimento'}</h3><span>{selectedAttendance.file_name}</span></div><div className="analysisActions"><button className="criterionActionsBtn" onClick={()=>setSelectedAttendance(null)}>Fechar</button><button className="dangerBtn" disabled={busy} onClick={()=>deleteAttendanceEvaluation(selectedAttendance)}>Excluir avaliação</button></div></div>{selectedAttendance.status==='erro'?<div className="analysisError">{selectedAttendance.error_message||'Não foi possível analisar este atendimento.'}</div>:selectedAttendance.analysis?<><div className="analysisTopGrid"><div className="analysisSummary"><b>Parecer do especialista</b><p>{selectedAttendance.analysis.parecer_especialista||selectedAttendance.analysis.resumo}</p></div><div className="analysisScoreHero"><span>QUALIDADE DO ATENDIMENTO</span><strong>{selectedAttendance.analysis.quality_score_100??selectedAttendance.analysis.nota_total??'—'}<small> / 100</small></strong><em>{selectedAttendance.analysis.status_resolucao?.replaceAll('_',' ')||'—'}</em></div></div><div className="analysisFacts"><div><span>Solicitação do cliente</span><b>{selectedAttendance.analysis.solicitacao_cliente||'Não identificado'}</b></div><div><span>Primeira resposta</span><b>{selectedAttendance.analysis.tempo_resposta?.primeira_resposta_minutos!=null?`${selectedAttendance.analysis.tempo_resposta.primeira_resposta_minutos} min`:'Não identificado'}</b></div><div><span>Maior intervalo</span><b>{selectedAttendance.analysis.tempo_resposta?.maior_intervalo_relevante_minutos!=null?`${selectedAttendance.analysis.tempo_resposta.maior_intervalo_relevante_minutos} min`:'Não identificado'}</b></div><div><span>Contexto do tempo</span><b>{selectedAttendance.analysis.tempo_resposta?.observacao||'Sem observação'}</b></div></div><div className="analysisFacts"><div><span>Nota bruta de qualidade</span><b>{selectedAttendance.analysis.quality_score_100??'—'} / 100</b></div><div><span>Utilização do Script e Processos</span><b>{selectedAttendance.analysis.script_score_10??'—'} / 10</b></div><div><span>Justificativa da qualidade</span><b>{selectedAttendance.analysis.quality_score_justification||'—'}</b></div><div><span>Justificativa do script</span><b>{selectedAttendance.analysis.script_score_justification||'—'}</b></div></div>{selectedAttendance.analysis.script_checks?.length>0&&<div className="analysisCriteria"><div className="panelTitle"><div><h3>Utilização do Script e Processos</h3><span>Sete critérios avaliados com evidências</span></div></div>{selectedAttendance.analysis.script_checks.map((item,i)=><div className="analysisCard" key={item.criterion||i}><div className="analysisCardHead"><div><b>{item.criterion}</b><small>{item.status?.replaceAll('_',' ')}</small></div></div><p>{item.justification}</p>{item.evidence?.length>0&&<div className="evidence"><b>Evidências</b>{item.evidence.map((e,j)=><span key={j}>“{e}”</span>)}</div>}</div>)}</div>}<div className="analysisCriteria">{(selectedAttendance.analysis.criterios||[]).map((item,i)=>{const c=criteria.find(x=>x.id===item.criterion_id);return <div className="analysisCard" key={item.criterion_id||i}><div className="analysisCardHead"><div><b>{c?.name||'Critério'}</b><small>{c?.weight||0}% • diagnóstico complementar / 3</small></div><strong>{item.available&&item.score!==null?Number(item.score).toFixed(1):'N/A'}<small>/3</small></strong></div><p>{item.justification}</p>{item.references_used?.length>0&&<div className="evidence"><b>Base utilizada</b>{item.references_used.map((r,j)=><span key={j}>{r.name} • v{r.version}</span>)}</div>}{item.evidence?.length>0&&<div className="evidence"><b>Evidências</b>{item.evidence.map((e,j)=><span key={j}>“{e}”</span>)}</div>}{item.attention_points?.length>0&&<div className="attention"><b>Pontos de atenção</b>{item.attention_points.map((e,j)=><span key={j}>{e}</span>)}</div>}</div>})}</div></>:<div className="emptyMini">A análise ainda está em processamento.</div>}</div>}</div>}
   {tab==='historico'&&<div className="panel"><div className="panelTitle"><div><h3>Histórico de destaques</h3><span>Os ciclos concluídos aparecerão aqui.</span></div></div><div className="emptyState"><div className="bigIcon">★</div><b>Nenhum ciclo concluído</b><span>O histórico será alimentado automaticamente após o fechamento de cada período.</span></div></div>}
   </>}
   {modal&&<div className="modalWrap">{(modal==='team'||modal==='team-edit')?<div className="modal destaqueModal"><div className="modalHead"><div><p className="eyebrow">EQUIPE AVALIADA</p><h2>{teamForm.id?'Editar colaborador':'Novo colaborador'}</h2><span>Este cadastro é independente dos usuários que acessam o ELO.</span></div><button onClick={()=>setModal(null)}>×</button></div><form className="destaqueForm" onSubmit={saveTeamMember}><label>Nome completo<input required value={teamForm.full_name} onChange={e=>setTeamForm({...teamForm,full_name:e.target.value})} placeholder="Ex.: Ana Araújo"/></label><div className="formGrid"><label>Setor<input value={teamForm.sector} onChange={e=>setTeamForm({...teamForm,sector:e.target.value})} placeholder="Ex.: Atendimento"/></label><label>Status<select value={teamForm.status} onChange={e=>setTeamForm({...teamForm,status:e.target.value})}><option value="ativo">Ativo</option><option value="inativo">Inativo</option></select></label></div>{msg&&<div className="notice">{msg}</div>}<div className="formActions"><button type="button" className="secondary" onClick={()=>setModal(null)}>Cancelar</button><button className="primary" disabled={busy}>{busy?'Salvando…':'Salvar colaborador'}</button></div></form></div>:<div className="modal destaqueModal"><div className="modalHead"><div><p className="eyebrow">CONFIGURAÇÃO</p><h2>{form.id?'Editar critério':'Novo critério'}</h2><span>Defina como o ELO deve avaliar este indicador.</span></div><button onClick={()=>setModal(null)}>×</button></div><form className="destaqueForm" onSubmit={saveCriterion}><label>Nome<input required value={form.name} onChange={e=>setForm({...form,name:e.target.value})} placeholder="Ex.: Qualidade do atendimento"/></label><label>Descrição<textarea value={form.description} onChange={e=>setForm({...form,description:e.target.value})} placeholder="Explique exatamente o que deve ser observado..."/></label><div className="formGrid"><label>Peso (%)<input type="number" min="1" max="100" value={form.weight} onChange={e=>setForm({...form,weight:e.target.value})}/></label><label>Fonte da nota<select value={form.source} onChange={e=>setForm({...form,source:e.target.value})}><option value="ia">IA — PDF do atendimento</option><option value="sistema">Sistema — indicador automático</option><option value="manual">Manual — gestor</option></select></label></div><div className="formGrid"><label>Nota mínima<input type="number" min="0" max="3" step="0.1" value={form.min_score} onChange={e=>setForm({...form,min_score:e.target.value})}/></label><label className="checkLabel"><input type="checkbox" checked={form.required} onChange={e=>setForm({...form,required:e.target.checked})}/> Critério obrigatório para elegibilidade</label></div><label className="checkLabel"><input type="checkbox" checked={form.active} onChange={e=>setForm({...form,active:e.target.checked})}/> Critério ativo</label><div className="formActions"><button type="button" className="secondary" onClick={()=>setModal(null)}>Cancelar</button><button className="primary" disabled={busy}>{busy?'Salvando…':'Salvar critério'}</button></div></form></div>}</div>}
 </section>
}

function DemandasManager({currentUser}){
 const [rows,setRows]=useState([]); const [loading,setLoading]=useState(true); const [query,setQuery]=useState('');
 const [status,setStatus]=useState('todos'); const [priority,setPriority]=useState('todos'); const [modal,setModal]=useState(null); const [busy,setBusy]=useState(false); const [msg,setMsg]=useState('');
 const [form,setForm]=useState({id:'',title:'',description:'',category:'Operacional',priority:'media',status:'nova',responsible_id:'',due_date:''});
 const [users,setUsers]=useState([]);
 const load=async()=>{setLoading(true);let q=supabase.from('demandas').select('*').order('created_at',{ascending:false});const {data,error}=await q;if(!error){const {data:members}=await supabase.rpc('get_active_team_members');const map=Object.fromEntries((members||[]).map(m=>[m.id,m.full_name]));setRows((data||[]).map(d=>({...d,responsible_name:map[d.responsible_id]||null,creator_name:map[d.created_by]||null})));}else setMsg(error.message);setLoading(false)};
 const loadUsers=async()=>{const {data}=await supabase.from('profiles').select('id,full_name').eq('status','ativo').order('full_name');setUsers(data||[])};
 useEffect(()=>{load();loadUsers()},[]);
 const openNew=()=>{setForm({id:'',title:'',description:'',category:'Operacional',priority:'media',status:'nova',responsible_id:'',due_date:''});setMsg('');setModal('new')};
 const openEdit=(d)=>{setForm({id:d.id,title:d.title,description:d.description||'',category:d.category||'Operacional',priority:d.priority,status:d.status,responsible_id:d.responsible_id||'',due_date:d.due_date||''});setMsg('');setModal('edit')};
 const save=async(e)=>{e.preventDefault();setBusy(true);setMsg('');const payload={title:form.title,description:form.description,category:form.category,priority:form.priority,status:form.status,responsible_id:form.responsible_id||null,due_date:form.due_date||null};let result;if(modal==='new')result=await supabase.from('demandas').insert({...payload,created_by:(await supabase.auth.getUser()).data.user.id});else result=await supabase.from('demandas').update(payload).eq('id',form.id);if(result.error)setMsg(result.error.message||'Não foi possível salvar.');else{await load();setModal(null)}setBusy(false)};
 const remove=async(id)=>{if(!confirm('Excluir esta demanda?'))return;const {error}=await supabase.from('demandas').delete().eq('id',id);if(error)setMsg(error.message);else load()};
 const filtered=rows.filter(d=>`${d.title} ${d.description||''} ${d.category||''} ${d.responsible_name||''}`.toLowerCase().includes(query.toLowerCase())&&(status==='todos'||d.status===status)&&(priority==='todos'||d.priority===priority));
 const labelStatus={nova:'Nova',em_analise:'Em análise',em_andamento:'Em andamento',aguardando:'Aguardando',concluida:'Concluída',cancelada:'Cancelada'};
 const labelPriority={baixa:'Baixa',media:'Média',alta:'Alta',urgente:'Urgente'};
 const formatDate=d=>d?new Date(`${d}T00:00:00`).toLocaleDateString('pt-BR'):'—';
 return <section className="demandasPage"><div className="demandToolbar solicitacaoToolbar"><div className="search">⌕ <input value={query} onChange={e=>setQuery(e.target.value)} placeholder="Buscar demanda..."/></div><select className="filterSelect" value={status} onChange={e=>setStatus(e.target.value)}><option value="todos">Todos os status</option>{Object.entries(labelStatus).map(([v,l])=><option key={v} value={v}>{l}</option>)}</select><select className="filterSelect" value={priority} onChange={e=>setPriority(e.target.value)}><option value="todos">Todas as prioridades</option>{Object.entries(labelPriority).map(([v,l])=><option key={v} value={v}>{l}</option>)}</select><button className="primary" onClick={openNew}>＋ Nova demanda</button></div>
 <div className="demandSummary"><div><b>{rows.length}</b><span>Total</span></div><div><b>{rows.filter(x=>['nova','em_analise','em_andamento','aguardando'].includes(x.status)).length}</b><span>Em aberto</span></div><div><b>{rows.filter(x=>x.priority==='urgente'||x.priority==='alta').length}</b><span>Alta prioridade</span></div><div><b>{rows.filter(x=>x.status==='concluida').length}</b><span>Concluídas</span></div></div>
 <div className="panel tablePanel"><div className="table"><div className="tr demandRow th"><span>Demanda</span><span>Prioridade</span><span>Responsável</span><span>Prazo</span><span>Status</span><span></span></div>{loading?<div className="emptyState">Carregando demandas…</div>:filtered.map(d=><div className="tr demandRow" key={d.id}><span><b>{d.title}</b><small>{d.category}</small></span><span><i className={'priorityPill '+d.priority}>{labelPriority[d.priority]}</i></span><span>{d.responsible_name||'Não definido'}</span><span>{formatDate(d.due_date)}</span><span><i className={'demandStatus '+d.status}>{labelStatus[d.status]}</i></span><span className="moreActions"><button onClick={()=>openEdit(d)}>✎</button><button onClick={()=>remove(d.id)}>×</button></span></div>)}{!loading&&!filtered.length&&<div className="emptyState">Nenhuma demanda encontrada.</div>}</div></div>
 {modal&&<div className="modalWrap"><div className="modal demandModal"><div className="modalHead"><div><p className="eyebrow">GESTÃO DE DEMANDAS</p><h2>{modal==='new'?'Nova demanda':'Editar demanda'}</h2><span>Registre, atribua e acompanhe uma necessidade até sua conclusão.</span></div><button onClick={()=>setModal(null)}>×</button></div><form className="demandForm" onSubmit={save}><label>Título<input value={form.title} onChange={e=>setForm({...form,title:e.target.value})} required placeholder="Ex.: Atualizar procedimento de atendimento"/></label><label>Descrição<textarea value={form.description} onChange={e=>setForm({...form,description:e.target.value})} placeholder="Descreva o contexto, objetivo e resultado esperado." rows="4"/></label><div className="formGrid"><label>Categoria<select value={form.category} onChange={e=>setForm({...form,category:e.target.value})}><option>Operacional</option><option>Atendimento</option><option>Processos</option><option>Tecnologia</option><option>Pessoas</option><option>Administrativo</option><option>Outro</option></select></label><label>Prioridade<select value={form.priority} onChange={e=>setForm({...form,priority:e.target.value})}>{Object.entries(labelPriority).map(([v,l])=><option key={v} value={v}>{l}</option>)}</select></label></div><div className="formGrid"><label>Responsável<select value={form.responsible_id} onChange={e=>setForm({...form,responsible_id:e.target.value})}><option value="">Não definido</option>{users.map(u=><option key={u.id} value={u.id}>{u.full_name}</option>)}</select></label><label>Prazo<input type="date" value={form.due_date} onChange={e=>setForm({...form,due_date:e.target.value})}/></label></div>{modal==='edit'&&<label>Status<select value={form.status} onChange={e=>setForm({...form,status:e.target.value})}>{Object.entries(labelStatus).map(([v,l])=><option key={v} value={v}>{l}</option>)}</select></label>}{msg&&<div className="notice">{msg}</div>}<div className="formActions"><button type="button" className="secondary" onClick={()=>setModal(null)}>Cancelar</button><button className="primary" disabled={busy}>{busy?'Salvando…':modal==='new'?'Criar demanda':'Salvar alterações'}</button></div></form></div></div>}
 </section>
}

function SolicitacoesManager({currentUser,openSignal}){
 const [rows,setRows]=useState([]); const [users,setUsers]=useState([]); const [loading,setLoading]=useState(true);
 const [query,setQuery]=useState(''); const [status,setStatus]=useState('todos'); const [priority,setPriority]=useState('todos');
 const [modal,setModal]=useState(null); const [busy,setBusy]=useState(false); const [msg,setMsg]=useState('');
 const [form,setForm]=useState({id:'',title:'',description:'',category:'Operacional',priority:'media',status:'nova',responsible_id:'',due_date:'',observations:''});
 const lastSignal=useRef(openSignal);
 const labelStatus={nova:'Nova',em_analise:'Em análise',aprovada:'Aprovada',recusada:'Recusada',demanda_gerada:'Demanda gerada'};
 const labelPriority={baixa:'Baixa',media:'Média',alta:'Alta',urgente:'Urgente'};
 const load=async()=>{setLoading(true);const {data,error}=await supabase.from('solicitacoes').select('*').order('created_at',{ascending:false});if(error)setMsg(error.message);else{const {data:members}=await supabase.rpc('get_active_team_members');const map=Object.fromEntries((members||[]).map(m=>[m.id,m.full_name]));setRows((data||[]).map(x=>({...x,title:x.titulo,description:x.descricao,category:x.categoria,priority:x.prioridade,status:x.status,responsible_id:x.responsavel_id,due_date:x.prazo_desejado,observations:x.observacoes,solicitante_name:map[x.solicitante_id]||'Usuário',responsavel_name:map[x.responsavel_id]||'Não definido'})));}setLoading(false)};
 const loadUsers=async()=>{const {data}=await supabase.rpc('get_active_team_members');setUsers(data||[])};
 useEffect(()=>{load();loadUsers()},[]);
 useEffect(()=>{if(openSignal!==lastSignal.current){lastSignal.current=openSignal;if(openSignal>0)openNew()}},[openSignal]);
 const openNew=()=>{setForm({id:'',title:'',description:'',category:'Operacional',priority:'media',status:'nova',responsible_id:'',due_date:'',observations:''});setMsg('');setModal('new')};
 const openEdit=x=>{setForm({id:x.id,title:x.title,description:x.description||'',category:x.category||'Operacional',priority:x.priority,status:x.status,responsible_id:x.responsible_id||'',due_date:x.due_date||'',observations:x.observations||''});setMsg('');setModal('edit')};
 const save=async e=>{e.preventDefault();setBusy(true);setMsg('');let result;if(modal==='new'){result=await supabase.from('solicitacoes').insert({solicitante_id:(await supabase.auth.getUser()).data.user.id,titulo:form.title,descricao:form.description,categoria:form.category,prioridade:form.priority,responsavel_id:form.responsible_id||null,prazo_desejado:form.due_date||null,status:'nova',observacoes:form.observations});}else{result=await supabase.from('solicitacoes').update({titulo:form.title,descricao:form.description,categoria:form.category,prioridade:form.priority,responsavel_id:form.responsible_id||null,prazo_desejado:form.due_date||null,status:form.status,observacoes:form.observations}).eq('id',form.id)}if(result.error)setMsg(result.error.message);else{await load();setModal(null)}setBusy(false)};
 const changeStatus=async(x,next)=>{const {error}=await supabase.from('solicitacoes').update({status:next}).eq('id',x.id);if(error)setMsg(error.message);else load()};
 const remove=async id=>{if(!confirm('Excluir esta solicitação?'))return;const {error}=await supabase.from('solicitacoes').delete().eq('id',id);if(error)setMsg(error.message);else load()};
 const filtered=rows.filter(x=>(`${x.title} ${x.description||''} ${x.category||''} ${x.solicitante_name||''} ${x.responsavel_name||''}`).toLowerCase().includes(query.toLowerCase())&&(status==='todos'||x.status===status)&&(priority==='todos'||x.priority===priority));
 const counts={total:rows.length,nova:rows.filter(x=>x.status==='nova').length,analise:rows.filter(x=>x.status==='em_analise').length,aprovada:rows.filter(x=>x.status==='aprovada').length};
 const date=d=>d?new Date(`${d}T00:00:00`).toLocaleDateString('pt-BR'):'—';
 return <section className="solicitacoesPage"><div className="demandSummary requestSummary"><div className="requestStat"><div className="requestStatTop"><span className="requestStatIcon">◈</span><span>VISÃO GERAL</span></div><strong>{counts.total}</strong><b>Total de solicitações</b><small>Registradas no ELO</small></div><div className="requestStat"><div className="requestStatTop"><span className="requestStatIcon">＋</span><span>ENTRADA</span></div><strong>{counts.nova}</strong><b>Novas</b><small>Aguardando análise</small></div><div className="requestStat"><div className="requestStatTop"><span className="requestStatIcon">◷</span><span>ANÁLISE</span></div><strong>{counts.analise}</strong><b>Em análise</b><small>Em avaliação</small></div><div className="requestStat"><div className="requestStatTop"><span className="requestStatIcon">✓</span><span>APROVAÇÃO</span></div><strong>{counts.aprovada}</strong><b>Aprovadas</b><small>Prontas para demanda</small></div></div>
 <div className="demandToolbar solicitacaoToolbar"><div className="search">⌕ <input value={query} onChange={e=>setQuery(e.target.value)} placeholder="Buscar solicitação..."/></div><select className="filterSelect" value={status} onChange={e=>setStatus(e.target.value)}><option value="todos">Todos os status</option>{Object.entries(labelStatus).map(([v,l])=><option key={v} value={v}>{l}</option>)}</select><select className="filterSelect" value={priority} onChange={e=>setPriority(e.target.value)}><option value="todos">Todas as prioridades</option>{Object.entries(labelPriority).map(([v,l])=><option key={v} value={v}>{l}</option>)}</select></div>
 {msg&&<div className="notice">{msg}</div>}
 <section className="panel tablePanel solicitacaoTablePanel"><div className="table"><div className="tr th"><span>Solicitação</span><span>Solicitante</span><span>Prioridade</span><span>Responsável</span><span>Prazo</span><span>Status</span><span></span></div>{loading?<div className="emptyState">Carregando solicitações…</div>:filtered.map(x=><div className="tr" key={x.id}><span><b>{x.title}</b><small>{x.category||'Sem categoria'}</small></span><span>{x.solicitante_name}</span><span>{labelPriority[x.priority]}</span><span>{x.responsavel_name}</span><span>{date(x.prazo_desejado)}</span><span className="status">{labelStatus[x.status]}</span><span className="more"><button onClick={()=>openEdit(x)}>✎</button></span></div>)}{!loading&&!filtered.length&&<div className="emptyState">Nenhuma solicitação encontrada.</div>}</div></section>
 {modal&&<div className="modalWrap"><div className="modal solicitacaoModal"><div className="modalHead"><div><p className="eyebrow">SOLICITAÇÕES</p><h2>{modal==='new'?'Nova solicitação':'Editar solicitação'}</h2><span>Registre e acompanhe uma necessidade até sua transformação em demanda.</span></div><button onClick={()=>setModal(null)}>×</button></div><form onSubmit={save} className="userForm solicitacaoForm"><label>Título<input value={form.title} onChange={e=>setForm({...form,title:e.target.value})} required placeholder="Ex.: Solicitar novo material de atendimento"/></label><label>Descrição<textarea value={form.description} onChange={e=>setForm({...form,description:e.target.value})} rows="4" placeholder="Descreva o que está sendo solicitado..."/></label><div className="formGrid"><label>Categoria<select value={form.category} onChange={e=>setForm({...form,category:e.target.value})}><option>Operacional</option><option>Administrativo</option><option>Tecnologia</option><option>Pessoas</option><option>Processos</option><option>Outro</option></select></label><label>Prioridade<select value={form.priority} onChange={e=>setForm({...form,priority:e.target.value})}>{Object.entries(labelPriority).map(([v,l])=><option key={v} value={v}>{l}</option>)}</select></label></div><div className="formGrid"><label>Responsável pela análise<select value={form.responsible_id} onChange={e=>setForm({...form,responsible_id:e.target.value})}><option value="">Não definido</option>{users.map(u=><option key={u.id} value={u.id}>{u.full_name}</option>)}</select></label><label>Prazo desejado<input type="date" value={form.due_date} onChange={e=>setForm({...form,due_date:e.target.value})}/></label></div>{modal==='edit'&&<label>Status<select value={form.status} onChange={e=>setForm({...form,status:e.target.value})}>{Object.entries(labelStatus).map(([v,l])=><option key={v} value={v}>{l}</option>)}</select></label>}<label>Observações<textarea value={form.observations} onChange={e=>setForm({...form,observations:e.target.value})} rows="3"/></label>{msg&&<div className="notice">{msg}</div>}<div className="formActions"><button type="button" className="secondary" onClick={()=>setModal(null)}>Cancelar</button><button className="primary" disabled={busy}>{busy?'Salvando…':modal==='new'?'Criar solicitação':'Salvar alterações'}</button></div></form></div></div>}</section>
}

function RelatoriosManager({currentUser}){
 const DEFAULT_CATS=['Geral','Atendimento','Equipe','Operacional','Resultado','Ocorrência','Treinamento'];
 const pad=n=>String(n).padStart(2,'0');
 const iso=d=>`${d.getFullYear()}-${pad(d.getMonth()+1)}-${pad(d.getDate())}`;
 const today=iso(new Date());
 const br=s=>s?s.split('-').reverse().join('/'):'—';
 const weekRange=s=>{const [y,m,d]=s.split('-').map(Number);const dt=new Date(y,m-1,d);const off=(dt.getDay()+6)%7;const a=new Date(y,m-1,d-off);const b=new Date(y,m-1,d-off+6);return [iso(a),iso(b)]};
 const monthRange=s=>{const [y,m]=s.split('-').map(Number);return [iso(new Date(y,m-1,1)),iso(new Date(y,m,0))]};
 const [tab,setTab]=useState('observacoes');
 const [obs,setObs]=useState([]); const [reports,setReports]=useState([]); const [loading,setLoading]=useState(true);
 const [msg,setMsg]=useState(''); const [busy,setBusy]=useState(false);
 const [query,setQuery]=useState(''); const [catFilter,setCatFilter]=useState('todas');
 const [modal,setModal]=useState(null); const [form,setForm]=useState({id:'',obs_date:today,category:'Geral',title:'',content:''});
 const [kind,setKind]=useState('semanal'); const [refDate,setRefDate]=useState(today); const [month,setMonth]=useState(today.slice(0,7)); const [from,setFrom]=useState(today); const [to,setTo]=useState(today);
 const [selected,setSelected]=useState([]); const [selCat,setSelCat]=useState('todas'); const [includeSolutions,setIncludeSolutions]=useState(false); const [reportTitle,setReportTitle]=useState(''); const [openReport,setOpenReport]=useState(null); const [editingReport,setEditingReport]=useState(false); const [editDraft,setEditDraft]=useState(null);
 const [catRows,setCatRows]=useState([]); const [catForm,setCatForm]=useState({new:'',editId:'',editName:''});
 const [links,setLinks]=useState({}); const [dm,setDm]=useState(null); const [teamMembers,setTeamMembers]=useState([]); const [verModal,setVerModal]=useState(null);
 const [hQuery,setHQuery]=useState(''); const [hKind,setHKind]=useState('todos'); const [hFrom,setHFrom]=useState(''); const [hTo,setHTo]=useState(''); const [hLimit,setHLimit]=useState(30); const [hMore,setHMore]=useState(false); const [hLoading,setHLoading]=useState(false);
 const activeCats=catRows.filter(c=>c.active).map(c=>c.name);
 const CATS=activeCats.length?activeCats:DEFAULT_CATS;
 const catOptions=(current)=>current&&!CATS.includes(current)?[...CATS,current]:CATS;
 const range=kind==='semanal'?weekRange(refDate||today):kind==='mensal'?monthRange(month||today.slice(0,7)):[from,to];
 const rangeOk=!!range[0]&&!!range[1]&&range[1]>=range[0];
 const loadObs=async()=>{const {data,error}=await supabase.from('relatorio_observacoes').select('*').order('obs_date',{ascending:false}).order('created_at',{ascending:false}).limit(1000);if(error)setMsg(error.message);else setObs(data||[])};
 const loadCats=async()=>{const {data,error}=await supabase.from('relatorio_categorias').select('*').order('sort_order').order('name');if(!error)setCatRows(data||[])};
 const loadReports=async()=>{setHLoading(true);let q=supabase.from('relatorios').select('id,kind,title,period_start,period_end,observation_count,generated_by_ai,created_at,created_by').order('created_at',{ascending:false}).limit(hLimit+1);if(hQuery.trim())q=q.ilike('title',`%${hQuery.trim().replace(/[%_,()]/g,' ')}%`);if(hKind!=='todos')q=q.eq('kind',hKind);if(hFrom)q=q.gte('period_end',hFrom);if(hTo)q=q.lte('period_start',hTo);const {data,error}=await q;if(error)setMsg(error.message);else{setHMore((data||[]).length>hLimit);setReports((data||[]).slice(0,hLimit))}setHLoading(false)};
 useEffect(()=>{(async()=>{setLoading(true);await Promise.all([loadObs(),loadCats()]);setLoading(false)})()},[]);
 useEffect(()=>{const t=setTimeout(loadReports,250);return()=>clearTimeout(t)},[hQuery,hKind,hFrom,hTo,hLimit]);
 const inRange=rangeOk?obs.filter(o=>o.obs_date>=range[0]&&o.obs_date<=range[1]):[];
 const visibleRange=inRange.filter(o=>selCat==='todas'||o.category===selCat);
 const selectedInRange=inRange.filter(o=>selected.includes(o.id));
 useEffect(()=>{setSelected(inRange.map(o=>o.id));setSelCat('todas')},[range[0],range[1],loading]);
 useEffect(()=>{const ids=new Set(obs.map(o=>o.id));setSelected(p=>p.filter(id=>ids.has(id)))},[obs]);
 const toggleSel=id=>setSelected(p=>p.includes(id)?p.filter(x=>x!==id):[...p,id]);
 const selectVisible=()=>setSelected(p=>[...new Set([...p,...visibleRange.map(o=>o.id)])]);
 const clearVisible=()=>setSelected(p=>p.filter(id=>!visibleRange.some(o=>o.id===id)));
 const readFnError=async(fn)=>{if(fn.error?.name==='FunctionsFetchError')return 'a Edge Function não respondeu. Confirme se ela foi publicada com o nome exato e consulte os logs dela no Supabase (Edge Functions → Logs).';if(fn.data?.error)return fn.data.error;const ctx=fn.error?.context;if(ctx&&typeof ctx.clone==='function'){try{const b=await ctx.clone().json();if(b?.error)return b.error}catch{}}return fn.error?.message||'Erro desconhecido.'};
 const openNew=()=>{setForm({id:'',obs_date:today,category:CATS[0]||'Geral',title:'',content:''});setMsg('');setModal('obs')};
 const openEdit=o=>{setForm({id:o.id,obs_date:o.obs_date,category:o.category,title:o.title,content:o.content||''});setMsg('');setModal('obs')};
 const saveObs=async(e)=>{e.preventDefault();setBusy(true);setMsg('');const payload={obs_date:form.obs_date,category:form.category,title:form.title.trim(),content:form.content.trim()||null};let r;if(form.id)r=await supabase.from('relatorio_observacoes').update(payload).eq('id',form.id);else r=await supabase.from('relatorio_observacoes').insert({...payload,created_by:(await supabase.auth.getUser()).data.user.id});if(r.error)setMsg(r.error.message);else{await loadObs();setModal(null)}setBusy(false)};
 const removeObs=async(id)=>{if(!confirm('Excluir esta observação?'))return;const {error}=await supabase.from('relatorio_observacoes').delete().eq('id',id);if(error)setMsg(error.message);else loadObs()};
 const removeReport=async(id)=>{if(!confirm('Excluir este relatório?'))return;const {error}=await supabase.from('relatorios').delete().eq('id',id);if(error)setMsg(error.message);else{if(openReport?.id===id)setOpenReport(null);loadReports()}};
 const generate=async()=>{if(!rangeOk){setMsg('Informe um período válido.');return}if(!selectedInRange.length){setMsg('Selecione ao menos uma observação.');return}if(selectedInRange.length>500){setMsg('Selecione no máximo 500 observações por relatório.');return}setBusy(true);setMsg('');const fn=await supabase.functions.invoke('generate-report',{body:{kind,period_start:range[0],period_end:range[1],observation_ids:selectedInRange.map(o=>o.id),include_solutions:includeSolutions,title:reportTitle.trim()||undefined}});if(fn.error||fn.data?.success===false){setMsg(`Não foi possível gerar o relatório: ${await readFnError(fn)}`)}else{await loadReports();const {data}=await supabase.from('relatorios').select('*').eq('id',fn.data.id).maybeSingle();if(data){setOpenReport(data);setTab('historico');setReportTitle('')}if(fn.data?.warning)setMsg(`Relatório gerado sem IA: ${fn.data.warning}`)}setBusy(false)};
 const toText=r=>{const c=r.content||{};const L=[r.title,`Observações analisadas: ${r.observation_count}`,'','RESUMO EXECUTIVO',c.resumo_executivo||''];const add=(t,a)=>{if(a?.length){L.push('',t,...a.map(x=>`- ${x}`))}};add('DESTAQUES',c.destaques);add('PONTOS DE ATENÇÃO',c.pontos_de_atencao);if(c.solucoes?.length){L.push('','POSSÍVEIS SOLUÇÕES (sugestões a validar)');c.solucoes.forEach(x=>{L.push(`${x.problema}${x.prioridade?` [prioridade ${prioLabel[x.prioridade]||x.prioridade}]`:''}`,...(x.solucoes||[]).map(y=>`  - ${y}`))})}if(c.por_categoria?.length){L.push('','POR CATEGORIA');c.por_categoria.forEach(x=>L.push(`${x.categoria}: ${x.resumo}`))}add('PRÓXIMOS PASSOS',c.proximos_passos);return L.join('\n')};
 const copyReport=async(r)=>{try{await navigator.clipboard.writeText(toText(r));setMsg('Relatório copiado para a área de transferência.')}catch{setMsg('Não foi possível copiar automaticamente.')}};
 const beginEditReport=(r)=>{const c=r.content||{};setEditDraft({title:r.title||'',resumo_executivo:c.resumo_executivo||'',destaques:(c.destaques||[]).join('\n'),pontos_de_atencao:(c.pontos_de_atencao||[]).join('\n'),por_categoria:(c.por_categoria||[]).map(x=>`${x.categoria||''} | ${x.resumo||''}`).join('\n'),proximos_passos:(c.proximos_passos||[]).join('\n'),solucoes:(c.solucoes||[]).map(x=>`${x.problema||''} | ${(x.solucoes||[]).join(' ; ')}${x.prioridade?` | ${x.prioridade}`:''}`).join('\n')});setEditingReport(true);setMsg('')};
 const saveReportEdits=async()=>{if(!openReport||!editDraft)return;setBusy(true);setMsg('');const original=openReport.content||{};const lines=(v)=>v.split('\n').map(x=>x.trim()).filter(Boolean);const categories=lines(editDraft.por_categoria).map(line=>{const i=line.indexOf('|');return i<0?{categoria:'Geral',resumo:line}:{categoria:line.slice(0,i).trim()||'Geral',resumo:line.slice(i+1).trim()}});const solutionItems=lines(editDraft.solucoes||'').map(line=>{const [pr,sl,pri]=line.split('|').map(x=>x.trim());const prioridade=(pri||'').toLowerCase().replace('é','e');return{problema:pr||'',solucoes:(sl||'').split(';').map(x=>x.trim()).filter(Boolean),prioridade:['alta','media','baixa'].includes(prioridade)?prioridade:'media'}}).filter(x=>x.problema&&x.solucoes.length);const content={...original,resumo_executivo:editDraft.resumo_executivo.trim(),destaques:lines(editDraft.destaques),pontos_de_atencao:lines(editDraft.pontos_de_atencao),por_categoria:categories,proximos_passos:lines(editDraft.proximos_passos)};if(solutionItems.length){content.solucoes=solutionItems;content.include_solutions=true}else{delete content.solucoes;content.include_solutions=false}const {data,error}=await supabase.from('relatorios').update({title:editDraft.title.trim(),content}).eq('id',openReport.id).select('*').single();if(error){setMsg(`Não foi possível salvar as alterações: ${error.message}`)}else{setOpenReport(data);setReports(prev=>prev.map(x=>x.id===data.id?data:x));setEditingReport(false);setEditDraft(null);setMsg('Relatório atualizado com sucesso.')}setBusy(false)};
 const addSolutions=async(r)=>{setBusy(true);setMsg('');const fn=await supabase.functions.invoke('generate-report',{body:{action:'add_solutions',report_id:r.id}});if(fn.error||fn.data?.success===false)setMsg(`Não foi possível gerar as soluções: ${await readFnError(fn)}`);else{const {data}=await supabase.from('relatorios').select('*').eq('id',r.id).single();if(data){setOpenReport(data);setReports(p=>p.map(x=>x.id===data.id?data:x))}setMsg(fn.data?.count?'Soluções incluídas no relatório.':'A IA não identificou problemas nas observações; nenhuma solução foi incluída.')}setBusy(false)};
 const removeSolutions=async(r)=>{if(!confirm('Remover as soluções deste relatório?'))return;setBusy(true);setMsg('');const {solucoes,...rest}=r.content||{};const {data,error}=await supabase.from('relatorios').update({content:{...rest,include_solutions:false}}).eq('id',r.id).select('*').single();if(error)setMsg(`Não foi possível remover as soluções: ${error.message}`);else{setOpenReport(data);setReports(p=>p.map(x=>x.id===data.id?data:x));setMsg('Soluções removidas do relatório.')}setBusy(false)};
 const prioLabel={alta:'Alta',media:'Média',baixa:'Baixa'};
 const demStatus={nova:'Nova',em_analise:'Em análise',em_andamento:'Em andamento',aguardando:'Aguardando',concluida:'Concluída',cancelada:'Cancelada'};
 const openById=async(id)=>{setMsg('');setEditingReport(false);setEditDraft(null);const {data,error}=await supabase.from('relatorios').select('*').eq('id',id).single();if(error)setMsg(error.message);else setOpenReport(data)};
 const loadLinks=async(id)=>{const {data}=await supabase.from('relatorio_solucao_demandas').select('problema,solucao,demanda_id,demandas(title,status)').eq('report_id',id).not('demanda_id','is',null);const m={};(data||[]).forEach(l=>{m[l.problema+'\u0001'+l.solucao]=l});setLinks(m)};
 useEffect(()=>{if(openReport?.id)loadLinks(openReport.id);else setLinks({})},[openReport?.id]);
 const openDemand=(r,x,y)=>{const pr=['alta','media','baixa'].includes(x.prioridade)?x.prioridade:'media';setDm({problema:x.problema,solucao:y,form:{title:y.length>110?y.slice(0,107)+'…':y,description:`Origem: ${r.title} (${br(r.period_start)} a ${br(r.period_end)})\nProblema identificado: ${x.problema}\nSolução sugerida: ${y}`,category:'Operacional',priority:pr,responsible_id:'',due_date:''}});setMsg('');if(!teamMembers.length)supabase.rpc('get_active_team_members').then(({data})=>setTeamMembers(data||[]))};
 const createDemand=async(e)=>{e.preventDefault();if(!dm||!openReport)return;setBusy(true);setMsg('');const f=dm.form;const uid=(await supabase.auth.getUser()).data.user.id;const {data,error}=await supabase.from('demandas').insert({title:f.title.trim(),description:f.description.trim()||null,category:f.category,priority:f.priority,status:'nova',responsible_id:f.responsible_id||null,due_date:f.due_date||null,created_by:uid}).select('id').single();if(error){setMsg(`Não foi possível criar a demanda: ${error.message}`);setBusy(false);return}const lk=await supabase.from('relatorio_solucao_demandas').insert({report_id:openReport.id,problema:dm.problema,solucao:dm.solucao,demanda_id:data.id,created_by:uid});setMsg(lk.error?`Demanda criada, mas o vínculo com o relatório não foi salvo: ${lk.error.message}`:'Demanda criada e vinculada à solução. Acompanhe no módulo Demandas.');setDm(null);await loadLinks(openReport.id);setBusy(false)};
 const downloadPdf=async(r)=>{setBusy(true);setMsg('Gerando PDF no servidor…');const fn=await supabase.functions.invoke('report-pdf',{body:{report_id:r.id}});if(fn.error||fn.data?.success===false){setMsg(`Não foi possível gerar o PDF: ${await readFnError(fn)}`)}else{try{const bin=atob(fn.data.base64);const bytes=new Uint8Array(bin.length);for(let i=0;i<bin.length;i++)bytes[i]=bin.charCodeAt(i);const url=URL.createObjectURL(new Blob([bytes],{type:'application/pdf'}));const a=document.createElement('a');a.href=url;a.download=fn.data.filename||'relatorio.pdf';document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),4000);setMsg('PDF gerado e baixado.')}catch{setMsg('O PDF foi gerado, mas o download falhou.')}}setBusy(false)};
 const duplicateReport=async(id)=>{setBusy(true);setMsg('');const {data:src,error:e1}=await supabase.from('relatorios').select('*').eq('id',id).single();if(e1){setMsg(e1.message);setBusy(false);return}const uid=(await supabase.auth.getUser()).data.user.id;const {data,error}=await supabase.from('relatorios').insert({kind:src.kind,title:`${src.title} (cópia)`.slice(0,200),period_start:src.period_start,period_end:src.period_end,observation_count:src.observation_count,content:src.content,generated_by_ai:src.generated_by_ai,model:src.model,created_by:uid}).select('*').single();if(error)setMsg(`Não foi possível duplicar: ${error.message}`);else{await loadReports();setTab('historico');setOpenReport(data);setMsg('Relatório duplicado. A cópia pode ser editada sem alterar o original.')}setBusy(false)};
 const openVersions=async(r)=>{setMsg('');const {data,error}=await supabase.from('relatorio_versoes').select('*').eq('report_id',r.id).order('version_no',{ascending:false});if(error){setMsg(`Não foi possível carregar as versões: ${error.message}`);return}setVerModal({list:data||[]})};
 const restoreVersion=async(v)=>{if(!confirm(`Restaurar a versão ${v.version_no}? O texto atual será guardado como uma nova versão.`))return;setBusy(true);setMsg('');const {data,error}=await supabase.from('relatorios').update({title:v.title,content:v.content}).eq('id',v.report_id).select('*').single();if(error)setMsg(`Não foi possível restaurar: ${error.message}`);else{setOpenReport(data);setReports(p=>p.map(x=>x.id===data.id?{...x,title:data.title}:x));setEditingReport(false);setEditDraft(null);setVerModal(null);setMsg(`Versão ${v.version_no} restaurada.`)}setBusy(false)};
 const addCat=async(e)=>{e.preventDefault();const name=catForm.new.trim();if(!name)return;setBusy(true);setMsg('');const {error}=await supabase.from('relatorio_categorias').insert({name,sort_order:(catRows.length+1)*10});if(error)setMsg(error.code==='23505'?'Já existe uma categoria com este nome.':error.message);else{setCatForm({...catForm,new:''});await loadCats();setMsg('Categoria adicionada.')}setBusy(false)};
 const saveCatName=async(c)=>{const name=catForm.editName.trim();if(!name||name===c.name){setCatForm({...catForm,editId:'',editName:''});return}setBusy(true);setMsg('');const {error}=await supabase.rpc('relatorio_renomear_categoria',{p_id:c.id,p_novo:name});if(error)setMsg(error.message);else{setCatForm({...catForm,editId:'',editName:''});await Promise.all([loadCats(),loadObs()]);setMsg('Categoria renomeada. As observações existentes foram atualizadas.')}setBusy(false)};
 const toggleCat=async(c)=>{setBusy(true);setMsg('');const {error}=await supabase.from('relatorio_categorias').update({active:!c.active}).eq('id',c.id);if(error)setMsg(error.message);else await loadCats();setBusy(false)};
 const removeCat=async(c)=>{if(obs.some(o=>o.category===c.name)){setMsg('Esta categoria possui observações. Desative-a em vez de excluir.');return}if(!confirm(`Excluir a categoria “${c.name}”?`))return;setBusy(true);setMsg('');const {error}=await supabase.from('relatorio_categorias').delete().eq('id',c.id);if(error)setMsg(error.message);else await loadCats();setBusy(false)};
 const filtered=obs.filter(o=>`${o.title} ${o.content||''} ${o.category}`.toLowerCase().includes(query.toLowerCase())&&(catFilter==='todas'||o.category===catFilter));
 const kindLabel={semanal:'Semanal',mensal:'Mensal',personalizado:'Personalizado'};
 const ReportDoc=({r})=>{const c=r.content||{};const editing=editingReport&&openReport?.id===r.id;const lines=(value)=>String(value||'').split('\n').filter(Boolean);return <article className="reportDoc"><header className="reportCover"><div className="reportBrand"><img src={grupoSystemLogo} alt="Grupo System Saúde"/></div><div className="reportCoverLabel">GRUPO SYSTEM SAÚDE</div><p className="eyebrow">RELATÓRIO {kindLabel[r.kind]?.toUpperCase()}</p>{editing?<input className="reportEditTitle" aria-label="Título do relatório" value={editDraft.title} onChange={e=>setEditDraft({...editDraft,title:e.target.value})}/>:<h2>{r.title}</h2>}<div className="reportMeta"><div><span>PERÍODO ANALISADO</span><b>{br(r.period_start)} a {br(r.period_end)}</b></div><div><span>REGISTROS CONSIDERADOS</span><b>{r.observation_count} observações</b></div><div><span>EMISSÃO</span><b>{br((r.created_at||new Date().toISOString()).slice(0,10))}</b></div></div><div className="reportActions noPrint">{editing?<><button className="filter" disabled={busy} onClick={()=>{setEditingReport(false);setEditDraft(null);setMsg('')}}>Cancelar edição</button><button className="primary" disabled={busy||!editDraft?.title.trim()} onClick={saveReportEdits}>{busy?'Salvando…':'Salvar alterações'}</button></>:<><button className="filter" onClick={()=>copyReport(r)}>⧉ Copiar</button><button className="filter" disabled={busy} onClick={()=>downloadPdf(r)}>⬇ Baixar PDF</button><button className="filter" onClick={()=>window.print()}>⎙ Imprimir</button>{c.solucoes?.length?<button className="filter" disabled={busy} onClick={()=>removeSolutions(r)}>Remover soluções</button>:<button className="filter" disabled={busy} onClick={()=>addSolutions(r)}>{busy?'Gerando…':'✦ Incluir soluções'}</button>}<button className="filter" onClick={()=>openVersions(r)}>↶ Versões</button><button className="filter" disabled={busy} onClick={()=>duplicateReport(r.id)}>⧉ Duplicar</button><button className="primary" onClick={()=>beginEditReport(r)}>✎ Editar relatório</button></>}</div></header><div className="reportStatus">{r.generated_by_ai?'Documento elaborado com apoio de IA, com base nas observações registradas.':'Documento consolidado automaticamente a partir das observações registradas.'}</div>
  {c.aviso&&<div className="notice warn">{c.aviso}</div>}
  <section><h3>Resumo executivo</h3>{editing?<textarea className="reportEditArea" aria-label="Resumo executivo" rows="5" value={editDraft.resumo_executivo} onChange={e=>setEditDraft({...editDraft,resumo_executivo:e.target.value})}/>:<p>{c.resumo_executivo}</p>}</section>
  {c.contagem_por_categoria&&<div className="reportChips">{Object.entries(c.contagem_por_categoria).map(([k,v])=><i key={k}>{k}: <b>{v}</b></i>)}</div>}
  {(editing||!!c.destaques?.length)&&<section><h3>Destaques</h3>{editing?<textarea className="reportEditArea" aria-label="Destaques, um por linha" rows="4" value={editDraft.destaques} onChange={e=>setEditDraft({...editDraft,destaques:e.target.value})}/>:<ul>{c.destaques.map((x,i)=><li key={i}>{x}</li>)}</ul>}{editing&&<small className="reportEditHint">Um destaque por linha.</small>}</section>}
  {(editing||!!c.pontos_de_atencao?.length)&&<section><h3>Pontos de atenção</h3>{editing?<textarea className="reportEditArea" aria-label="Pontos de atenção, um por linha" rows="4" value={editDraft.pontos_de_atencao} onChange={e=>setEditDraft({...editDraft,pontos_de_atencao:e.target.value})}/>:<ul>{c.pontos_de_atencao.map((x,i)=><li key={i}>{x}</li>)}</ul>}{editing&&<small className="reportEditHint">Um ponto por linha.</small>}</section>}
  {(editing||!!c.solucoes?.length)&&<section className="reportSolutions"><h3>Possíveis soluções</h3>{editing?<><textarea className="reportEditArea" aria-label="Possíveis soluções" rows="5" value={editDraft.solucoes} onChange={e=>setEditDraft({...editDraft,solucoes:e.target.value})}/><small className="reportEditHint">Um problema por linha, no formato: Problema | solução 1 ; solução 2 | prioridade (alta, media ou baixa). Deixe vazio para remover a seção.</small></>:<><p className="solutionNote">Sugestões elaboradas por IA a partir dos problemas registrados nas observações. Devem ser validadas pela gestão antes da aplicação.</p>{c.solucoes.map((x,i)=><div className="solutionItem" key={i}><div className="solutionHead"><b>{x.problema}</b>{x.prioridade&&<i className={'priorityPill '+x.prioridade}>Prioridade {prioLabel[x.prioridade]||x.prioridade}</i>}</div><ul>{(x.solucoes||[]).map((y,j)=>{const lk=links[x.problema+'\u0001'+y];return <li key={j}><span>{y}</span>{lk?<em className="demandBadge" title={lk.demandas?.title||''}>✓ Demanda criada{lk.demandas?.status?` · ${demStatus[lk.demandas.status]||lk.demandas.status}`:''}</em>:<button type="button" className="demandBtn noPrint" onClick={()=>openDemand(r,x,y)}>＋ Criar demanda</button>}</li>})}</ul></div>)}</>}</section>}
  {(editing||!!c.por_categoria?.length)&&<section><h3>Por categoria</h3>{editing?<><textarea className="reportEditArea" aria-label="Análise por categoria" rows="5" value={editDraft.por_categoria} onChange={e=>setEditDraft({...editDraft,por_categoria:e.target.value})}/><small className="reportEditHint">Uma categoria por linha, no formato: Categoria | descrição.</small></>:c.por_categoria.map((x,i)=><div className="reportCat" key={i}><b>{x.categoria}</b><p>{x.resumo}</p></div>)}</section>}
  {(editing||!!c.proximos_passos?.length)&&<section className="reportNextSteps"><h3>Plano de ação e próximos passos</h3>{editing?<><textarea className="reportEditArea" aria-label="Plano de ação, um passo por linha" rows="4" value={editDraft.proximos_passos} onChange={e=>setEditDraft({...editDraft,proximos_passos:e.target.value})}/><small className="reportEditHint">Um próximo passo por linha.</small></>:<ul>{c.proximos_passos.map((x,i)=><li key={i}><span className="actionIndex">{String(i+1).padStart(2,'0')}</span><span>{x}</span></li>)}</ul>}</section>}{!editing&&!!c.observacoes_incluidas?.length&&<section className="reportRecords"><h3>Registros considerados ({c.observacoes_incluidas.length})</h3><ul>{c.observacoes_incluidas.map((x,i)=><li key={i}><span>{br(x.data)}</span><i>{x.categoria}</i><span>{x.titulo}</span></li>)}</ul></section>}<footer className="reportFooter"><div><b>Grupo System Saúde</b><span>Documento gerado a partir dos registros disponíveis no sistema de gestão.</span></div><span>Uso interno</span></footer></article>};
 return <section className="relatoriosPage">
  <div className="destaqueTabs noPrint">{[['observacoes','Observações'],['gerar','Gerar relatório'],['historico','Relatórios gerados'],['categorias','Categorias']].map(([id,l])=><button key={id} className={tab===id?'active':''} onClick={()=>{setTab(id);setMsg('')}}>{l}</button>)}</div>
  {msg&&<div className="notice noPrint">{msg}</div>}
  {tab==='observacoes'&&<>
   <div className="demandToolbar solicitacaoToolbar noPrint"><div className="search">⌕ <input value={query} onChange={e=>setQuery(e.target.value)} placeholder="Buscar observação..."/></div><select className="filterSelect" value={catFilter} onChange={e=>setCatFilter(e.target.value)}><option value="todas">Todas as categorias</option>{catOptions().map(c=><option key={c}>{c}</option>)}</select><span></span><button className="primary" onClick={openNew}>＋ Nova observação</button></div>
   <div className="panel tablePanel"><div className="table"><div className="tr obsRow th"><span>Data</span><span>Observação</span><span>Categoria</span><span></span></div>
    {loading?<div className="emptyState">Carregando observações…</div>:filtered.map(o=><div className="tr obsRow" key={o.id}><span>{br(o.obs_date)}</span><span><b>{o.title}</b>{o.content&&<small>{o.content}</small>}</span><span><i className="priorityPill media">{o.category}</i></span><span className="moreActions"><button onClick={()=>openEdit(o)}>✎</button><button onClick={()=>removeObs(o.id)}>×</button></span></div>)}
    {!loading&&!filtered.length&&<div className="emptyState">Nenhuma observação registrada. Clique em “Nova observação” para começar.</div>}</div></div></>}
  {tab==='gerar'&&<div className="panel reportBuilder reportBuilderWide noPrint"><div><p className="eyebrow">FILTRO DE PERÍODO</p><h2>Gerar relatório</h2><span className="muted">Escolha o período, marque as observações que farão parte do relatório e gere quantos relatórios distintos precisar.</span></div>
   <div className="kindSwitch">{Object.entries(kindLabel).map(([k,l])=><button key={k} className={kind===k?'active':''} onClick={()=>setKind(k)}>{l}</button>)}</div>
   <div className="formGrid">{kind==='semanal'&&<label>Escolha qualquer dia da semana<input type="date" value={refDate} onChange={e=>setRefDate(e.target.value)}/></label>}{kind==='mensal'&&<label>Mês<input type="month" value={month} onChange={e=>setMonth(e.target.value)}/></label>}{kind==='personalizado'&&<><label>De<input type="date" value={from} onChange={e=>setFrom(e.target.value)}/></label><label>Até<input type="date" value={to} onChange={e=>setTo(e.target.value)}/></label></>}</div>
   <div className="periodBox"><div><small>Período</small><b>{rangeOk?`${br(range[0])} a ${br(range[1])}`:'Período inválido'}</b></div><div><small>Observações selecionadas</small><b>{selectedInRange.length} de {inRange.length}</b></div></div>
   <label>Nome do relatório (opcional)<input value={reportTitle} maxLength={150} onChange={e=>setReportTitle(e.target.value)} placeholder="Ex.: Ocorrências de atendimento — 2ª semana"/></label>
   <div className="obsPicker"><div className="obsPickerHead"><b>Observações do período</b><div className="obsPickerTools"><select className="filterSelect" value={selCat} onChange={e=>setSelCat(e.target.value)}><option value="todas">Todas as categorias</option>{[...new Set([...CATS,...inRange.map(o=>o.category)])].map(c=><option key={c} value={c}>{c} ({inRange.filter(o=>o.category===c).length})</option>)}</select><button type="button" className="filter" onClick={selectVisible} disabled={!visibleRange.length}>Marcar visíveis</button><button type="button" className="filter" onClick={clearVisible} disabled={!visibleRange.length}>Desmarcar visíveis</button></div></div>
    <div className="obsPickerList">{loading?<div className="emptyState">Carregando observações…</div>:visibleRange.map(o=><label className={'obsPick'+(selected.includes(o.id)?' on':'')} key={o.id}><input type="checkbox" checked={selected.includes(o.id)} onChange={()=>toggleSel(o.id)}/><span className="obsPickDate">{br(o.obs_date)}</span><span className="obsPickText"><b>{o.title}</b>{o.content&&<small>{o.content}</small>}</span><i className="priorityPill media">{o.category}</i></label>)}{!loading&&!visibleRange.length&&<div className="emptyState">{inRange.length?'Nenhuma observação nesta categoria.':'Não há observações neste período.'}</div>}</div></div>
   <label className="solutionToggle"><input type="checkbox" checked={includeSolutions} onChange={e=>setIncludeSolutions(e.target.checked)}/><span><b>Incluir possíveis soluções no relatório</b><small>A IA sugere soluções para os problemas e ocorrências presentes nas observações selecionadas. São sugestões para validação, não fatos registrados. Você também pode incluí-las depois, no relatório já gerado.</small></span></label>
   <button className="primary" disabled={busy||!rangeOk||!selectedInRange.length} onClick={generate}>{busy?'Gerando relatório…':`Gerar relatório com ${selectedInRange.length} observaç${selectedInRange.length===1?'ão':'ões'}`}</button>{!!inRange.length&&!selectedInRange.length&&<span className="muted">Marque ao menos uma observação para gerar.</span>}</div>}
  {tab==='historico'&&<div className="reportsLayout"><div className="panel tablePanel noPrint"><div className="reportFilters"><div className="search">⌕ <input value={hQuery} onChange={e=>{setHQuery(e.target.value);setHLimit(30)}} placeholder="Buscar pelo nome..."/></div><select className="filterSelect" value={hKind} onChange={e=>{setHKind(e.target.value);setHLimit(30)}}><option value="todos">Todos os tipos</option>{Object.entries(kindLabel).map(([k,l])=><option key={k} value={k}>{l}</option>)}</select><label className="dateFilter">Período de<input type="date" value={hFrom} onChange={e=>{setHFrom(e.target.value);setHLimit(30)}}/></label><label className="dateFilter">até<input type="date" value={hTo} onChange={e=>{setHTo(e.target.value);setHLimit(30)}}/></label>{(hQuery||hKind!=='todos'||hFrom||hTo)&&<button className="filter" onClick={()=>{setHQuery('');setHKind('todos');setHFrom('');setHTo('');setHLimit(30)}}>Limpar</button>}</div><div className="table"><div className="tr reportRow th"><span>Relatório</span><span>Tipo</span><span></span></div>{reports.map(r=><div className={'tr reportRow'+(openReport?.id===r.id?' selected':'')} key={r.id}><span><b>{r.title}</b><small>Período {br(r.period_start)} a {br(r.period_end)} · gerado em {new Date(r.created_at).toLocaleString('pt-BR')}</small></span><span><i className="priorityPill media">{kindLabel[r.kind]}</i></span><span className="moreActions"><button title="Abrir" onClick={()=>openById(r.id)}>👁</button><button title="Duplicar" disabled={busy} onClick={()=>duplicateReport(r.id)}>⧉</button><button title="Excluir" onClick={()=>removeReport(r.id)}>×</button></span></div>)}{!reports.length&&<div className="emptyState">{hLoading?'Carregando…':'Nenhum relatório encontrado.'}</div>}{hMore&&<button className="filter loadMore" disabled={hLoading} onClick={()=>setHLimit(l=>l+30)}>{hLoading?'Carregando…':'Carregar mais'}</button>}</div></div>
   <div>{openReport?<><div className="noPrint">{msg&&<div className="notice">{msg}</div>}</div>{ReportDoc({r:openReport})}</>:<div className="panel noPrint"><div className="emptyState">Selecione um relatório para visualizar.</div></div>}</div></div>}
  {tab==='categorias'&&<div className="panel reportBuilder reportBuilderWide noPrint"><div><p className="eyebrow">CADASTRO</p><h2>Categorias das observações</h2><span className="muted">Crie, renomeie ou desative categorias. Ao renomear, as observações já registradas passam a usar o novo nome; relatórios já gerados mantêm o texto original.</span></div>
   {!catRows.length&&<div className="notice warn">Cadastro de categorias indisponível. Execute o arquivo <b>relatorios-v0170-categorias-versoes-demandas.sql</b> no Supabase.</div>}
   <form className="catAdd" onSubmit={addCat}><input value={catForm.new} maxLength={60} onChange={e=>setCatForm({...catForm,new:e.target.value})} placeholder="Nova categoria (ex.: Financeiro)"/><button className="primary" disabled={busy||!catForm.new.trim()}>＋ Adicionar</button></form>
   <div className="catList">{catRows.map(c=>{const n=obs.filter(o=>o.category===c.name).length;const editing=catForm.editId===c.id;return <div className={'catRow'+(c.active?'':' off')} key={c.id}>{editing?<input autoFocus maxLength={60} value={catForm.editName} onChange={e=>setCatForm({...catForm,editName:e.target.value})} onKeyDown={e=>{if(e.key==='Enter')saveCatName(c);if(e.key==='Escape')setCatForm({...catForm,editId:'',editName:''})}}/>:<b>{c.name}</b>}<small>{n} observaç{n===1?'ão':'ões'}{!c.active&&' · inativa'}</small><span className="catActions">{editing?<><button className="filter" disabled={busy} onClick={()=>saveCatName(c)}>Salvar</button><button className="filter" onClick={()=>setCatForm({...catForm,editId:'',editName:''})}>Cancelar</button></>:<><button className="filter" onClick={()=>setCatForm({...catForm,editId:c.id,editName:c.name})}>Renomear</button><button className="filter" disabled={busy} onClick={()=>toggleCat(c)}>{c.active?'Desativar':'Ativar'}</button><button className="filter" disabled={busy||n>0} title={n>0?'Possui observações':'Excluir'} onClick={()=>removeCat(c)}>Excluir</button></>}</span></div>})}</div></div>}
  {dm&&<div className="modalWrap"><div className="modal demandModal"><div className="modalHead"><div><p className="eyebrow">DEMANDAS</p><h2>Criar demanda a partir da solução</h2><span>A demanda será criada com status “Nova” e vinculada a este relatório.</span></div><button onClick={()=>setDm(null)}>×</button></div>
   <form className="demandForm" onSubmit={createDemand}><label>Título<input required maxLength={200} value={dm.form.title} onChange={e=>setDm({...dm,form:{...dm.form,title:e.target.value}})}/></label><label>Descrição<textarea rows="5" value={dm.form.description} onChange={e=>setDm({...dm,form:{...dm.form,description:e.target.value}})}/></label>
   <div className="formGrid"><label>Categoria<select value={dm.form.category} onChange={e=>setDm({...dm,form:{...dm.form,category:e.target.value}})}>{['Operacional','Atendimento','Processos','Tecnologia','Pessoas','Administrativo','Outros'].map(c=><option key={c}>{c}</option>)}</select></label><label>Prioridade<select value={dm.form.priority} onChange={e=>setDm({...dm,form:{...dm.form,priority:e.target.value}})}><option value="baixa">Baixa</option><option value="media">Média</option><option value="alta">Alta</option><option value="urgente">Urgente</option></select></label></div>
   <div className="formGrid"><label>Responsável<select value={dm.form.responsible_id} onChange={e=>setDm({...dm,form:{...dm.form,responsible_id:e.target.value}})}><option value="">Não definido</option>{teamMembers.map(m=><option key={m.id} value={m.id}>{m.full_name}</option>)}</select></label><label>Prazo desejado<input type="date" value={dm.form.due_date} onChange={e=>setDm({...dm,form:{...dm.form,due_date:e.target.value}})}/></label></div>
   {msg&&<div className="notice">{msg}</div>}<div className="formActions"><button type="button" className="filter" onClick={()=>setDm(null)}>Cancelar</button><button className="primary" disabled={busy||!dm.form.title.trim()}>{busy?'Criando…':'Criar demanda'}</button></div></form></div></div>}
  {verModal&&<div className="modalWrap"><div className="modal demandModal"><div className="modalHead"><div><p className="eyebrow">RELATÓRIOS</p><h2>Versões do relatório</h2><span>Cada alteração guarda a versão anterior. Restaurar também pode ser desfeito.</span></div><button onClick={()=>setVerModal(null)}>×</button></div>
   <div className="versionList">{!verModal.list.length&&<div className="emptyState">Este relatório ainda não foi alterado. A primeira alteração guardará a versão original.</div>}{verModal.list.map(v=>{const vc=v.content||{};const rs=vc.resumo_executivo||'';return <div className="versionItem" key={v.id}><div><b>Versão {v.version_no}{v.version_no===1?' — estado inicial':''}</b><small>Substituída em {new Date(v.created_at).toLocaleString('pt-BR')}{v.replaced_by_name?` por ${v.replaced_by_name}`:''}</small><p>{rs.slice(0,220)}{rs.length>220?'…':''}</p><small>{(vc.destaques||[]).length} destaques · {(vc.pontos_de_atencao||[]).length} pontos de atenção · {(vc.solucoes||[]).length} soluções</small></div><button className="filter" disabled={busy} onClick={()=>restoreVersion(v)}>↶ Restaurar</button></div>})}</div></div></div>}
  {modal==='obs'&&<div className="modalWrap"><div className="modal demandModal"><div className="modalHead"><div><p className="eyebrow">RELATÓRIOS</p><h2>{form.id?'Editar observação':'Nova observação'}</h2><span>Registre fatos do dia a dia. Eles serão agrupados nos relatórios.</span></div><button onClick={()=>setModal(null)}>×</button></div>
   <form className="demandForm" onSubmit={saveObs}><div className="formGrid"><label>Data<input type="date" required value={form.obs_date} onChange={e=>setForm({...form,obs_date:e.target.value})}/></label><label>Categoria<select value={form.category} onChange={e=>setForm({...form,category:e.target.value})}>{catOptions(form.category).map(c=><option key={c}>{c}</option>)}</select></label></div><label>Título<input required value={form.title} onChange={e=>setForm({...form,title:e.target.value})} placeholder="Ex.: Queda de sistema no período da manhã"/></label><label>Detalhes<textarea rows="5" value={form.content} onChange={e=>setForm({...form,content:e.target.value})} placeholder="Descreva o que aconteceu, quem participou e o resultado."/></label>{msg&&<div className="notice">{msg}</div>}<div className="formActions"><button type="button" className="filter" onClick={()=>setModal(null)}>Cancelar</button><button className="primary" disabled={busy}>{busy?'Salvando…':'Salvar'}</button></div></form></div></div>}
 </section>
}
const OP_CONFIG={
 ideias:{table:'ideias',title:'Ideias',singular:'ideia',fields:[['title','Título','text',true],['description','Descrição','textarea',false],['impact','Impacto','select',true,['baixo','medio','alto']],['status','Status','select',true,['nova','em_analise','aprovada','em_desenvolvimento','implementada','recusada']]],columns:[['title','Ideia'],['impact','Impacto'],['status','Status'],['created_at','Criada em']]},
 projetos:{table:'projetos',title:'Projetos',singular:'projeto',fields:[['title','Nome do projeto','text',true],['description','Descrição','textarea',false],['priority','Prioridade','select',true,['baixa','media','alta','urgente']],['status','Status','select',true,['planejamento','em_andamento','pausado','concluido','cancelado']],['start_date','Data de início','date',false],['due_date','Prazo','date',false]],columns:[['title','Projeto'],['priority','Prioridade'],['status','Status'],['due_date','Prazo']]},
 agenda:{table:'agenda_eventos',title:'Agenda',singular:'evento',fields:[['title','Título do evento','text',true],['description','Descrição','textarea',false],['event_date','Data','date',true],['start_time','Horário inicial','time',false],['end_time','Horário final','time',false],['participants','Participantes','text',false]],columns:[['title','Evento'],['event_date','Data'],['start_time','Início'],['participants','Participantes']]},
 reunioes:{table:'reunioes',title:'Reuniões',singular:'reunião',fields:[['title','Título da reunião','text',true],['description','Pauta','textarea',false],['meeting_date','Data e hora','datetime-local',true],['participants','Participantes','text',false],['minutes','Ata / encaminhamentos','textarea',false],['status','Status','select',true,['agendada','realizada','cancelada']]],columns:[['title','Reunião'],['meeting_date','Data'],['participants','Participantes'],['status','Status']]},
 arquivos:{table:'arquivos_registros',title:'Arquivos',singular:'registro de arquivo',fields:[['title','Nome do arquivo','text',true],['description','Descrição','textarea',false],['category','Categoria','text',true],['file_url','Link do arquivo','url',false]],columns:[['title','Arquivo'],['category','Categoria'],['file_url','Link'],['created_at','Adicionado em']]}
};
function OperationalRecordsManager({page,currentUser}){
 const cfg=OP_CONFIG[page];const [rows,setRows]=useState([]);const [loading,setLoading]=useState(true);const [busy,setBusy]=useState(false);const [query,setQuery]=useState('');const [modal,setModal]=useState(null);const [msg,setMsg]=useState('');const empty=()=>Object.fromEntries(cfg.fields.map(f=>[f[0],f[2]==='select'?(f[4]?.[0]||''): '']));const [form,setForm]=useState(empty);
 const load=async()=>{setLoading(true);const {data,error}=await supabase.from(cfg.table).select('*').order('created_at',{ascending:false});if(error){setMsg(`Não foi possível carregar ${cfg.title.toLowerCase()}. Execute o SQL ELO V0.15.0 e confira as permissões.`);setRows([])}else{setRows(data||[]);setMsg('')}setLoading(false)};
 useEffect(()=>{load()},[page]);const openNew=()=>{setForm(empty());setModal('new');setMsg('')};const openEdit=x=>{setForm({...empty(),...x});setModal('edit');setMsg('')};
 const save=async e=>{e.preventDefault();setBusy(true);setMsg('');const payload={};cfg.fields.forEach(f=>payload[f[0]]=form[f[0]]===''?null:form[f[0]]);if(cfg.table==='reunioes'&&payload.meeting_date)payload.meeting_date=new Date(payload.meeting_date).toISOString();let result;if(modal==='new'){payload.created_by=(await supabase.auth.getUser()).data.user.id;result=await supabase.from(cfg.table).insert(payload)}else result=await supabase.from(cfg.table).update(payload).eq('id',form.id);if(result.error)setMsg(result.error.message);else{setModal(null);await load()}setBusy(false)};
 const remove=async id=>{if(!confirm(`Excluir este ${cfg.singular}? Esta ação não pode ser desfeita.`))return;const {error}=await supabase.from(cfg.table).delete().eq('id',id);if(error)setMsg(error.message);else load()};
 const filtered=rows.filter(x=>cfg.fields.some(f=>String(x[f[0]]??'').toLowerCase().includes(query.toLowerCase())));const display=(key,v)=>{if(v===null||v===undefined||v==='')return '—';if(key.endsWith('_date'))return String(v).slice(0,10).split('-').reverse().join('/');if(key==='created_at')return new Date(v).toLocaleDateString('pt-BR');if(key==='meeting_date')return new Date(v).toLocaleString('pt-BR');return String(v)};
 return <section className="demandasPage"><div className="demandToolbar solicitacaoToolbar"><div className="search">⌕ <input value={query} onChange={e=>setQuery(e.target.value)} placeholder={`Buscar ${cfg.singular}...`}/></div><span className="muted">{rows.length} registro(s)</span><button className="primary" onClick={openNew}>＋ Novo(a) {cfg.singular}</button></div>{msg&&<div className="notice warn" style={{marginBottom:12}}>{msg}</div>}<div className="panel tablePanel"><div className="table"><div className="tr th" style={{gridTemplateColumns:`repeat(${cfg.columns.length},minmax(120px,1fr)) 70px`}}>{cfg.columns.map(c=><span key={c[0]}>{c[1]}</span>)}<span>Ações</span></div>{loading?<div className="emptyState">Carregando...</div>:filtered.map(x=><div className="tr" key={x.id} style={{gridTemplateColumns:`repeat(${cfg.columns.length},minmax(120px,1fr)) 70px`}}>{cfg.columns.map(c=><span key={c[0]}>{c[0]==='file_url'&&x[c[0]]?<a href={x[c[0]]} target="_blank" rel="noreferrer">Abrir arquivo ↗</a>:display(c[0],x[c[0]])}</span>)}<span className="moreActions"><button onClick={()=>openEdit(x)} title="Editar">✎</button><button onClick={()=>remove(x.id)} title="Excluir">×</button></span></div>)}{!loading&&!filtered.length&&<div className="emptyState">Nenhum registro encontrado. Clique em “Novo” para começar.</div>}</div></div>{modal&&<div className="modalWrap"><div className="modal demandModal"><div className="modalHead"><div><p className="eyebrow">GESTÃO OPERACIONAL</p><h2>{modal==='new'?'Novo registro':'Editar registro'} · {cfg.title}</h2><span>Os dados são salvos no Supabase e usados nos indicadores quando aplicável.</span></div><button onClick={()=>setModal(null)}>×</button></div><form className="demandForm" onSubmit={save}>{cfg.fields.map(f=><label key={f[0]}>{f[1]}{f[2]==='textarea'?<textarea rows="3" required={f[3]} value={form[f[0]]||''} onChange={e=>setForm({...form,[f[0]]:e.target.value})}/>:f[2]==='select'?<select required={f[3]} value={form[f[0]]||''} onChange={e=>setForm({...form,[f[0]]:e.target.value})}>{f[4].map(v=><option key={v} value={v}>{v.replaceAll('_',' ')}</option>)}</select>:<input type={f[2]} required={f[3]} value={form[f[0]]||''} onChange={e=>setForm({...form,[f[0]]:e.target.value})}/>}</label>)}{msg&&<div className="notice warn">{msg}</div>}<div className="formActions"><button type="button" className="secondary" onClick={()=>setModal(null)}>Cancelar</button><button className="primary" disabled={busy}>{busy?'Salvando…':'Salvar registro'}</button></div></form></div></div>}</section>
}
function IndicadoresManager({currentUser}){
 const [rows,setRows]=useState([]);const [goals,setGoals]=useState([]);const [loading,setLoading]=useState(true);const [busy,setBusy]=useState(false);const [msg,setMsg]=useState('');const [tab,setTab]=useState('dados');const [file,setFile]=useState(null);const [query,setQuery]=useState('');const [form,setForm]=useState({metric_date:new Date().toISOString().slice(0,10),sector:'',collaborator_name:'',indicator_name:'Produtividade',value:'',unit:'quantidade',source:'manual',notes:''});const [goal,setGoal]=useState({indicator_name:'Produtividade',period_key:new Date().toISOString().slice(0,7),sector:'',target_value:'',unit:'quantidade'});
 const load=async()=>{setLoading(true);const [r,g]=await Promise.all([supabase.from('indicadores_registros').select('*').order('metric_date',{ascending:false}).limit(1000),supabase.from('indicadores_metas').select('*').order('period_key',{ascending:false}).limit(500)]);if(r.error)setMsg('Não foi possível carregar os indicadores. Execute o SQL ELO V0.15.0 e confira as permissões.');else setRows(r.data||[]);if(!g.error)setGoals(g.data||[]);setLoading(false)};useEffect(()=>{load()},[]);
 const save=async e=>{e.preventDefault();setBusy(true);setMsg('');const user=(await supabase.auth.getUser()).data.user;const {error}=await supabase.from('indicadores_registros').insert({...form,value:Number(form.value),created_by:user.id});if(error)setMsg(error.message);else{setMsg('Registro salvo.');setForm({...form,value:'',notes:''});await load()}setBusy(false)};
 const saveGoal=async e=>{e.preventDefault();setBusy(true);const user=(await supabase.auth.getUser()).data.user;const {error}=await supabase.from('indicadores_metas').upsert({...goal,target_value:Number(goal.target_value),created_by:user.id},{onConflict:'indicator_name,period_key,sector'});setMsg(error?error.message:'Meta salva.');if(!error)await load();setBusy(false)};
 const importCsv=async()=>{if(!file)return;setBusy(true);setMsg('');try{const txt=await file.text();const lines=txt.replace(/^\uFEFF/,'').split(/\r?\n/).filter(Boolean);if(lines.length<2)throw new Error('O CSV precisa ter cabeçalho e pelo menos uma linha.');const sep=lines[0].includes(';')?';':',';const headers=lines[0].split(sep).map(x=>x.trim().toLowerCase().replaceAll(' ','_'));const idx=(...names)=>headers.findIndex(h=>names.includes(h));const map={metric_date:idx('data','metric_date','data_indicador'),sector:idx('setor','sector'),collaborator_name:idx('colaborador','collaborator_name','nome'),indicator_name:idx('indicador','indicator_name','indicador_nome'),value:idx('valor','value'),unit:idx('unidade','unit'),notes:idx('observacao','observações','notes')};if(map.indicator_name<0||map.value<0)throw new Error('Cabeçalho obrigatório: indicador e valor. Campos aceitos: data, setor, colaborador, indicador, valor, unidade, observacao.');const user=(await supabase.auth.getUser()).data.user;const batch=crypto.randomUUID();const records=lines.slice(1).map((line,i)=>{const c=line.split(sep).map(x=>x.trim());const val=Number((c[map.value]||'').replace(',','.'));if(!Number.isFinite(val))throw new Error(`Valor inválido na linha ${i+2}.`);return {metric_date:map.metric_date>=0&&c[map.metric_date]?c[map.metric_date]:new Date().toISOString().slice(0,10),sector:map.sector>=0?c[map.sector]||null:null,collaborator_name:map.collaborator_name>=0?c[map.collaborator_name]||null:null,indicator_name:c[map.indicator_name],value:val,unit:map.unit>=0?c[map.unit]||'quantidade':'quantidade',source:'csv',notes:map.notes>=0?c[map.notes]||null:null,import_batch:batch,created_by:user.id}});if(records.some(r=>!r.indicator_name))throw new Error('Há indicador sem nome no CSV.');for(let i=0;i<records.length;i+=200){const {error}=await supabase.from('indicadores_registros').insert(records.slice(i,i+200));if(error)throw error}await supabase.from('indicadores_importacoes').insert({batch_id:batch,file_name:file.name,rows_imported:records.length,status:'concluida',created_by:user.id});setMsg(`${records.length} registro(s) importado(s). Confira os dados antes de usar em decisões.`);setFile(null);await load()}catch(e){setMsg(`Importação não concluída: ${e.message||'erro inesperado'}. Confira o CSV; não repita até verificar se houve inserção parcial.`)}setBusy(false)};
 const remove=async id=>{if(!confirm('Excluir este registro de indicador?'))return;const {error}=await supabase.from('indicadores_registros').delete().eq('id',id);setMsg(error?error.message:'Registro excluído.');if(!error)load()};const filtered=rows.filter(r=>`${r.indicator_name} ${r.sector||''} ${r.collaborator_name||''} ${r.source||''}`.toLowerCase().includes(query.toLowerCase()));const total=rows.length;const sum=rows.reduce((a,r)=>a+Number(r.value||0),0);const unique=[...new Set(rows.map(r=>r.indicator_name))].length;
 return <section className="demandasPage"><div className="demandSummary"><div><b>{total}</b><span>Registros carregados</span></div><div><b>{unique}</b><span>Indicadores diferentes</span></div><div><b>{rows.filter(r=>r.source==='csv').length}</b><span>Importados por CSV</span></div><div><b>{goals.length}</b><span>Metas cadastradas</span></div></div><div className="destaqueTabs" style={{marginBottom:16}}>{[['dados','Dados registrados'],['novo','Cadastro manual'],['importar','Importar CSV'],['metas','Metas']].map(([id,l])=><button key={id} className={tab===id?'active':''} onClick={()=>{setTab(id);setMsg('')}}>{l}</button>)}</div>{msg&&<div className="notice" style={{marginBottom:14}}>{msg}</div>}{tab==='dados'&&<div className="panel tablePanel"><div className="demandToolbar"><div className="search">⌕ <input value={query} onChange={e=>setQuery(e.target.value)} placeholder="Buscar indicador, setor ou colaborador"/></div><button className="filter" onClick={()=>load()}>↻ Atualizar</button></div><div className="table"><div className="tr th" style={{gridTemplateColumns:'1fr 1fr 1fr .7fr .7fr .7fr 50px'}}><span>Indicador</span><span>Setor</span><span>Colaborador</span><span>Data</span><span>Valor</span><span>Fonte</span><span></span></div>{loading?<div className="emptyState">Carregando...</div>:filtered.map(r=><div className="tr" key={r.id} style={{gridTemplateColumns:'1fr 1fr 1fr .7fr .7fr .7fr 50px'}}><span>{r.indicator_name}</span><span>{r.sector||'—'}</span><span>{r.collaborator_name||'—'}</span><span>{String(r.metric_date).split('-').reverse().join('/')}</span><span>{Number(r.value).toLocaleString('pt-BR')} {r.unit}</span><span>{r.source==='csv'?'CSV':'Manual'}</span><span className="moreActions"><button onClick={()=>remove(r.id)}>×</button></span></div>)}{!loading&&!filtered.length&&<div className="emptyState">Nenhum registro. Cadastre manualmente ou importe um CSV.</div>}</div></div>}{tab==='novo'&&<div className="panel"><div className="panelTitle"><div><h3>Registrar indicador</h3><span>Uma linha por indicador, colaborador e data.</span></div></div><form className="demandForm" onSubmit={save}><div className="formGrid"><label>Data<input type="date" required value={form.metric_date} onChange={e=>setForm({...form,metric_date:e.target.value})}/></label><label>Indicador<input required value={form.indicator_name} onChange={e=>setForm({...form,indicator_name:e.target.value})} placeholder="Ex.: atendimentos concluídos"/></label></div><div className="formGrid"><label>Setor<input value={form.sector} onChange={e=>setForm({...form,sector:e.target.value})} placeholder="Ex.: Atendimento"/></label><label>Colaborador<input value={form.collaborator_name} onChange={e=>setForm({...form,collaborator_name:e.target.value})}/></label></div><div className="formGrid"><label>Valor numérico<input type="number" step="any" required value={form.value} onChange={e=>setForm({...form,value:e.target.value})}/></label><label>Unidade<select value={form.unit} onChange={e=>setForm({...form,unit:e.target.value})}>{['quantidade','minutos','horas','percentual','pontos','R$'].map(v=><option key={v}>{v}</option>)}</select></label></div><label>Observações<textarea rows="3" value={form.notes} onChange={e=>setForm({...form,notes:e.target.value})}/></label><button className="primary" disabled={busy}>{busy?'Salvando…':'Salvar indicador'}</button></form></div>}{tab==='importar'&&<div className="panel"><div className="panelTitle"><div><h3>Importar planilha CSV</h3><span>Exportar Excel como CSV UTF-8. Cabeçalho mínimo: indicador;valor.</span></div></div><div className="notice">Campos aceitos: data, setor, colaborador, indicador, valor, unidade, observacao. Use vírgula ou ponto e vírgula como separador. Evite separadores dentro dos textos; não são interpretadas aspas CSV avançadas nesta versão.</div><label className="dropzone"><input type="file" accept=".csv,text/csv" onChange={e=>setFile(e.target.files?.[0]||null)}/><span>＋</span><b>{file?file.name:'Selecionar arquivo CSV'}</b><small>Os dados serão inseridos como novos registros; não há atualização automática nem deduplicação nesta primeira versão.</small></label><button className="primary" disabled={!file||busy} onClick={importCsv}>{busy?'Importando…':'Validar e importar CSV'}</button></div>}{tab==='metas'&&<div className="destaqueGrid"><div className="panel"><div className="panelTitle"><div><h3>Cadastrar meta</h3><span>Meta por indicador, período mensal e setor.</span></div></div><form className="demandForm" onSubmit={saveGoal}><label>Indicador<input required value={goal.indicator_name} onChange={e=>setGoal({...goal,indicator_name:e.target.value})}/></label><div className="formGrid"><label>Período (AAAA-MM)<input type="month" required value={goal.period_key} onChange={e=>setGoal({...goal,period_key:e.target.value})}/></label><label>Setor<input value={goal.sector} onChange={e=>setGoal({...goal,sector:e.target.value})}/></label></div><div className="formGrid"><label>Meta numérica<input type="number" step="any" required value={goal.target_value} onChange={e=>setGoal({...goal,target_value:e.target.value})}/></label><label>Unidade<input value={goal.unit} onChange={e=>setGoal({...goal,unit:e.target.value})}/></label></div><button className="primary" disabled={busy}>{busy?'Salvando…':'Salvar meta'}</button></form></div><div className="panel"><div className="panelTitle"><div><h3>Metas registradas</h3><span>As metas ficam registradas por período e setor. Defina a regra de agregação de cada indicador (soma, média ou percentual) antes de comparar com a meta.</span></div></div>{goals.map(g=><div className="priority" key={g.id}><span className="dot"></span><div><b>{g.indicator_name} · {g.period_key}</b><small>{g.sector||'Todos os setores'} · Meta: {g.target_value} {g.unit}</small></div></div>)}{!goals.length&&<div className="emptyState">Nenhuma meta cadastrada.</div>}</div></div>}</section>
}
function UserManager({onClose}){
 const [users,setUsers]=useState([]); const [query,setQuery]=useState(''); const [loading,setLoading]=useState(true);
 const [modal,setModal]=useState(null); const [busy,setBusy]=useState(false); const [msg,setMsg]=useState('');
 const [form,setForm]=useState({id:'',name:'',email:'',role:'colaborador',status:'ativo',password:''});
 const modules=['dashboard','demandas','solicitacoes','ideias','projetos','arquivos','destaques','agenda','reunioes','indicadores','relatorios'];
 const [permissions,setPermissions]=useState({});
 const labels={dashboard:'Dashboard',demandas:'Demandas',solicitacoes:'Solicitações',ideias:'Ideias',projetos:'Projetos',arquivos:'Arquivos',destaques:'Destaques',agenda:'Agenda',reunioes:'Reuniões',indicadores:'Indicadores',relatorios:'Relatórios'};
 const load=async()=>{setLoading(true);const {data,error}=await supabase.from('profiles').select('*').order('full_name');if(!error)setUsers(data||[]);setLoading(false)};
 useEffect(()=>{load()},[]);
 const openNew=()=>{setForm({id:'',name:'',email:'',role:'colaborador',status:'ativo',password:''});setMsg('');setModal('new')};
 const openEdit=(u)=>{setForm({id:u.id,name:u.full_name,email:u.email,role:u.role,status:u.status,password:''});setMsg('');setModal('edit')};
 const openPermissions=async(u)=>{setForm({id:u.id,name:u.full_name,email:u.email,role:u.role,status:u.status,password:''});setMsg('');const {data}=await supabase.from('user_permissions').select('*').eq('user_id',u.id);const map={};(data||[]).forEach(x=>map[x.module]={view:x.can_view,create:x.can_create,edit:x.can_edit,delete:x.can_delete});setPermissions(map);setModal('permissions')};
 const create=async e=>{e.preventDefault();setBusy(true);setMsg('');const res=await supabase.functions.invoke('admin-create-user',{body:{name:form.name,email:form.email,role:form.role,password:form.password}});if(res.error){setMsg(res.error.message||'Não foi possível criar o usuário.')}else{setMsg('Usuário criado com sucesso.');await load();setTimeout(()=>setModal(null),700)}setBusy(false)};
 const update=async e=>{e.preventDefault();setBusy(true);setMsg('');const {error}=await supabase.from('profiles').update({full_name:form.name,email:form.email,role:form.role,status:form.status,updated_at:new Date().toISOString()}).eq('id',form.id);if(error)setMsg('Não foi possível salvar as alterações.');else{setMsg('Alterações salvas.');await load();setTimeout(()=>setModal(null),700)}setBusy(false)};
 const toggleStatus=async(u)=>{const next=u.status==='ativo'?'inativo':'ativo';const {error}=await supabase.from('profiles').update({status:next,updated_at:new Date().toISOString()}).eq('id',u.id);if(!error)load()};
 const savePermissions=async()=>{setBusy(true);setMsg('');await supabase.from('user_permissions').delete().eq('user_id',form.id);const rows=[];modules.forEach(m=>{const x=permissions[m]||{};if(x.view||x.create||x.edit||x.delete)rows.push({user_id:form.id,module:m,can_view:!!x.view,can_create:!!x.create,can_edit:!!x.edit,can_delete:!!x.delete})});const {error}=rows.length?await supabase.from('user_permissions').insert(rows):{error:null};if(error)setMsg('Não foi possível salvar as permissões.');else{setMsg('Permissões salvas.');setTimeout(()=>setModal(null),700)}setBusy(false)};
 const filtered=users.filter(u=>(`${u.full_name} ${u.email} ${u.role}`.toLowerCase()).includes(query.toLowerCase()));
 return <div className="modalWrap wide"><div className="modal userModal"><div className="modalHead"><div><p className="eyebrow">ADMINISTRAÇÃO</p><h2>Usuários ELO</h2><span>Controle interno de acessos, perfis e permissões.</span></div><button onClick={onClose}>×</button></div>
 <div className="userToolbar"><div className="search">⌕ <input value={query} onChange={e=>setQuery(e.target.value)} placeholder="Buscar usuário..."/></div><button className="primary" onClick={openNew}>＋ Novo usuário</button></div>
 <div className="userTable"><div className="userRow head"><span>Usuário</span><span>Perfil</span><span>Status</span><span>Cadastro</span><span></span></div>{loading?<div className="emptyState">Carregando usuários…</div>:filtered.map(u=><div className="userRow" key={u.id}><span><b>{u.full_name}</b><small>{u.email}</small></span><span className="rolePill">{u.role}</span><span><i className={'statusDot '+u.status}></i>{u.status}</span><span>{new Date(u.created_at).toLocaleDateString('pt-BR')}</span><span className="userActions"><button onClick={()=>openPermissions(u)} title="Permissões">⚿</button><button onClick={()=>openEdit(u)} title="Editar">✎</button><button onClick={()=>toggleStatus(u)} title={u.status==='ativo'?'Inativar':'Ativar'}>{u.status==='ativo'?'◉':'○'}</button></span></div>)}{!loading&&!filtered.length&&<div className="emptyState">Nenhum usuário encontrado.</div>}</div>
 {modal==='new'&&<div className="subModal"><div className="modalHead"><div><h2>Novo usuário</h2><span>O acesso é criado exclusivamente pelo administrador.</span></div><button onClick={()=>setModal(null)}>×</button></div><form onSubmit={create} className="userForm"><label>Nome completo<input value={form.name} onChange={e=>setForm({...form,name:e.target.value})} required/></label><label>E-mail<input type="email" value={form.email} onChange={e=>setForm({...form,email:e.target.value})} required/></label><label>Senha inicial<input type="password" value={form.password} onChange={e=>setForm({...form,password:e.target.value})} minLength={8} required placeholder="Mínimo de 8 caracteres"/></label><label>Perfil<select value={form.role} onChange={e=>setForm({...form,role:e.target.value})}><option value="administrador">Administrador</option><option value="gestor">Gestor</option><option value="supervisor">Supervisor</option><option value="colaborador">Colaborador</option></select></label>{msg&&<div className="notice">{msg}</div>}<div className="formActions"><button type="button" className="secondary" onClick={()=>setModal(null)}>Cancelar</button><button className="primary" disabled={busy}>{busy?'Criando…':'Criar usuário'}</button></div></form></div>}
 {modal==='edit'&&<div className="subModal"><div className="modalHead"><div><h2>Editar usuário</h2><span>{form.email}</span></div><button onClick={()=>setModal(null)}>×</button></div><form onSubmit={update} className="userForm"><label>Nome completo<input value={form.name} onChange={e=>setForm({...form,name:e.target.value})} required/></label><label>E-mail<input type="email" value={form.email} onChange={e=>setForm({...form,email:e.target.value})} required/></label><label>Perfil<select value={form.role} onChange={e=>setForm({...form,role:e.target.value})}><option value="administrador">Administrador</option><option value="gestor">Gestor</option><option value="supervisor">Supervisor</option><option value="colaborador">Colaborador</option></select></label><label>Status<select value={form.status} onChange={e=>setForm({...form,status:e.target.value})}><option value="ativo">Ativo</option><option value="inativo">Inativo</option></select></label>{msg&&<div className="notice">{msg}</div>}<div className="formActions"><button type="button" className="secondary" onClick={()=>setModal(null)}>Cancelar</button><button className="primary" disabled={busy}>{busy?'Salvando…':'Salvar alterações'}</button></div></form></div>}
 {modal==='permissions'&&<div className="subModal permissionsModal"><div className="modalHead"><div><h2>Permissões</h2><span>{form.name} · controle por módulo</span></div><button onClick={()=>setModal(null)}>×</button></div><div className="permGrid"><div className="permHead"><span>Módulo</span><span>Ver</span><span>Criar</span><span>Editar</span><span>Excluir</span></div>{modules.map(m=><div className="permRow" key={m}><b>{labels[m]}</b>{['view','create','edit','delete'].map(k=><label key={k}><input type="checkbox" checked={!!permissions[m]?.[k]} onChange={e=>setPermissions({...permissions,[m]:{...(permissions[m]||{}),[k]:e.target.checked}})}/></label>)}</div>)}</div>{msg&&<div className="notice">{msg}</div>}<div className="formActions"><button className="secondary" onClick={()=>setModal(null)}>Cancelar</button><button className="primary" disabled={busy} onClick={savePermissions}>{busy?'Salvando…':'Salvar permissões'}</button></div></div>}
 </div></div>
}
function Root(){
 const [session,setSession]=useState(undefined);
 const [profile,setProfile]=useState(null);
 const [authError,setAuthError]=useState('');
 const [resetRoute,setResetRoute]=useState(()=>new URLSearchParams(window.location.search).get('reset-password')==='1');
 const returnToLogin=async()=>{
   if(supabase)await supabase.auth.signOut();
   window.history.replaceState({},document.title,window.location.pathname);
   setResetRoute(false);setSession(null);setProfile(null);
 };
 const loadSession=async()=>{
   if(!supabase){setSession(null);return}
   const {data:{session}}=await supabase.auth.getSession();
   setSession(session);
   if(session){
     const {data,error}=await supabase.from('profiles').select('*').eq('id',session.user.id).single();
     if(error||!data||data.status!=='ativo'){
       await supabase.auth.signOut();
       setSession(null);setProfile(null);
       setAuthError('Seu acesso não está ativo. Procure o administrador do ELO.');
       return;
     }
     setProfile(data);
   }
 };
 useEffect(()=>{
   if(!supabase){setSession(null);return}
   loadSession();
   const {data:{subscription}}=supabase.auth.onAuthStateChange(async (_e,s)=>{
     setSession(s);
     if(s){
       const {data,error}=await supabase.from('profiles').select('*').eq('id',s.user.id).single();
       if(error||!data||data.status!=='ativo'){
         await supabase.auth.signOut();
         setSession(null);setProfile(null);
         setAuthError('Seu acesso não está ativo. Procure o administrador do ELO.');
       }else{setProfile(data);setAuthError('')}
     }else setProfile(null);
   });
   return()=>subscription.unsubscribe();
 },[]);
 if(resetRoute){
   if(session===undefined)return <div className="loading">Validando link de recuperação…</div>;
   return <ResetPassword onBack={returnToLogin} hasSession={!!session}/>;
 }
 if(session===undefined)return <div className="loading">Carregando ELO…</div>;
 if(!session)return <Login onLogin={setSession}/>;
 if(!profile)return <div className="loading">Validando acesso…</div>;
 return <App session={session} profile={profile}/>;
}
createRoot(document.getElementById('root')).render(<Root/>);
